    const range = clamp(defender.range, 0, 20, 5);
    const catching = clamp(defender.catching ?? defender.fielding, 0, 20, 5);
    const pacePressure = context.pace === "hard" ? -0.25 : context.pace === "weak" ? -0.1 : 0;
