var CareerTransitionProgression = ((runtimeResolver, careerSpineContract) => {
  function clone(value) {
    if (value === undefined) return undefined;
    return JSON.parse(JSON.stringify(value));
  }

  function deepFreeze(value) {
    if (!value || typeof value !== "object" || Object.isFrozen(value)) return value;
    Object.values(value).forEach(deepFreeze);
    return Object.freeze(value);
  }

  function rejected(code, message, completedEventId) {
    return deepFreeze({
      status: "rejected",
      advanced: false,
      routeKey: null,
      completedEventId: clone(completedEventId),
      previousStep: null,
      nextStep: null,
      settlementRequired: false,
      issues: [{ code, message }]
    });
  }

  function canSafelyWriteOwnDataProperty(target, key) {
    try {
      const descriptor = Object.getOwnPropertyDescriptor(target, key);
      return !!descriptor
        && Object.prototype.hasOwnProperty.call(descriptor, "value")
        && descriptor.writable === true;
    } catch (_error) {
      return false;
    }
  }

  function getRouteLength(routeKey) {
    if (!careerSpineContract || typeof careerSpineContract.getCareerNetwork !== "function") {
      return null;
    }

    let network;
    try {
      network = careerSpineContract.getCareerNetwork();
    } catch (_error) {
      return null;
    }

    const matchingRoutes = Array.isArray(network?.initialRoutes)
      ? network.initialRoutes.filter(route => route.routeKey === routeKey)
      : [];
    if (matchingRoutes.length !== 1) return null;

    const route = matchingRoutes[0];
    const routeLength = (Array.isArray(route.exclusiveEventIds) ? route.exclusiveEventIds.length : 0)
      + (Array.isArray(route.sharedEventIds) ? route.sharedEventIds.length : 0);
    return routeLength > 0 ? routeLength : null;
  }

  function advanceTransition(playerState, completedEventId) {
    if (!playerState || typeof playerState !== "object" || Array.isArray(playerState)) {
      return rejected(
        "transition-progression-state-missing",
        "Adult Transition Progression requires a Player state object.",
        completedEventId
      );
    }

    if (playerState.forcedEventId) {
      return rejected(
        "transition-progression-forced-event-active",
        "A forced event cannot advance the underlying adult transition.",
        completedEventId
      );
    }

    if (!runtimeResolver || typeof runtimeResolver.resolveTransitionRuntime !== "function") {
      return rejected(
        "transition-runtime-resolver-unavailable",
        "Architecture Sprint 4.6 Runtime Resolver is unavailable.",
        completedEventId
      );
    }

    let runtimeResult;
    try {
      runtimeResult = runtimeResolver.resolveTransitionRuntime(playerState);
    } catch (_error) {
      return rejected(
        "transition-runtime-resolution-failed",
        "The current adult transition event could not be resolved.",
        completedEventId
      );
    }

    if (!runtimeResult || runtimeResult.resolved !== true || runtimeResult.status !== "resolved") {
      return rejected(
        "transition-runtime-unresolved",
        "The Player state is not eligible for adult transition progression.",
        completedEventId
      );
    }

    if (typeof completedEventId !== "string" || !completedEventId.trim()) {
      return rejected(
        "transition-completed-event-missing",
        "A completed transition event ID is required.",
        completedEventId
      );
    }

    if (completedEventId !== runtimeResult.eventId) {
      return rejected(
        "transition-completed-event-mismatch",
        "The completed event does not match the currently resolved transition event.",
        completedEventId
      );
    }

    const routeLength = getRouteLength(runtimeResult.routeKey);
    if (!Number.isInteger(routeLength)) {
      return rejected(
        "transition-route-contract-unavailable",
        "The resolved transition route has no unique Contract length.",
        completedEventId
      );
    }

    const previousStep = runtimeResult.transitionStep;
    if (!Number.isInteger(previousStep) || previousStep < 0 || previousStep >= routeLength) {
      return rejected(
        "transition-step-outside-contract",
        "The resolved transition step is outside the Contract route.",
        completedEventId
      );
    }

    if (!canSafelyWriteOwnDataProperty(playerState, "transitionStep")) {
      return rejected(
        "transition-step-not-writable",
        "transitionStep is not a writable own data property.",
        completedEventId
      );
    }

    const nextStep = previousStep + 1;
    const settlementRequired = nextStep === routeLength;
    try {
      playerState.transitionStep = nextStep;
    } catch (_error) {
      return rejected(
        "transition-step-write-failed",
        "transitionStep could not be advanced.",
        completedEventId
      );
    }

    return deepFreeze({
      status: "advanced",
      advanced: true,
      routeKey: runtimeResult.routeKey,
      completedEventId,
      previousStep,
      nextStep,
      settlementRequired,
      issues: []
    });
  }

  const api = Object.freeze({ advanceTransition });
  if (typeof window !== "undefined") window.CareerTransitionProgression = api;
  if (typeof module !== "undefined" && module.exports) module.exports = api;
  return api;
})(
  typeof CareerTransitionRuntimeResolver !== "undefined"
    ? CareerTransitionRuntimeResolver
    : typeof require === "function"
      ? require("./career-transition-runtime-resolver.js")
      : null,
  typeof CareerSpineContract !== "undefined"
    ? CareerSpineContract
    : typeof require === "function"
      ? require("./career-spine-contract.js")
      : null
);

sources.career-transition-resolver.js:
var GraduationTransitionResolver = ((careerSpineContract) => {
  function clone(value) {
    if (value === undefined) return undefined;
    return JSON.parse(JSON.stringify(value));
  }

  function deepFreeze(value) {
    if (!value || typeof value !== "object" || Object.isFrozen(value)) return value;
    Object.values(value).forEach(deepFreeze);
    return Object.freeze(value);
  }

  function unresolved(code, message, details) {
    return deepFreeze({
      status: "unresolved",
      resolved: false,
      target: null,
      issues: [{ code, message }],
      details: details ? clone(details) : null
    });
  }

  function resolveGraduationTransition(graduationState) {
    if (!graduationState || typeof graduationState !== "object" || Array.isArray(graduationState)) {
      return unresolved(
        "graduation-state-missing",
        "Graduation Transition Resolver 需要一份高中畢業狀態物件。"
      );
    }

    if (
      !careerSpineContract ||
      typeof careerSpineContract.getCareerNetwork !== "function" ||
      typeof careerSpineContract.getCareerNetworkSnapshot !== "function"
    ) {
      return unresolved(
        "career-network-contract-unavailable",
        "無法取得 Architecture Sprint 4.3 的成年職涯網路契約。"
      );
    }

    const snapshot = careerSpineContract.getCareerNetworkSnapshot(graduationState);
    if (snapshot.status !== "recognized" || snapshot.careerStage !== "high-school-exit") {
      return unresolved(
        "graduation-state-invalid",
        "輸入不是可供成年入口解析的合法高中畢業狀態。",
        { snapshotStatus: snapshot.status, nodeId: snapshot.nodeId, issues: snapshot.issues }
      );
    }

    if (snapshot.forcedEventId) {
      return unresolved(
        "graduation-state-not-stable",
        "高中畢業狀態仍有 forcedEventId，尚未形成穩定的成年轉換交接點。",
        { forcedEventId: snapshot.forcedEventId }
      );
    }

    const network = careerSpineContract.getCareerNetwork();
    const matchingRoutes = network.initialRoutes.filter(route =>
      Array.isArray(route.careerExits) && route.careerExits.includes(snapshot.careerExit)
    );

    if (matchingRoutes.length !== 1) {
      return unresolved(
        matchingRoutes.length === 0 ? "graduation-route-unmapped" : "graduation-route-ambiguous",
        matchingRoutes.length === 0
          ? "高中畢業出口沒有對應到成年職涯網路中的合法入口。"
          : "高中畢業出口同時對應到多個成年職涯入口。",
        { careerExit: snapshot.careerExit, matchingRouteCount: matchingRoutes.length }
      );
    }

    if (!Array.isArray(snapshot.actualNextNodeIds) || snapshot.actualNextNodeIds.length !== 1) {
      return unresolved(
        "adult-entry-node-ambiguous",
        "高中畢業節點沒有唯一的成年職涯下一節點。",
        { actualNextNodeIds: snapshot.actualNextNodeIds }
      );
    }

    const targetNode = network.adultNodes.find(node => node.nodeId === snapshot.actualNextNodeIds[0]);
    if (!targetNode || targetNode.networkRole !== "initial-route-and-shared-transition") {
      return unresolved(
        "adult-entry-node-missing",
        "高中畢業狀態指向的成年職涯入口不存在或不是合法入口節點。",
        { targetNodeId: snapshot.actualNextNodeIds[0] }
      );
    }

    const route = matchingRoutes[0];
    if (!Array.isArray(route.exclusiveEventIds) || route.exclusiveEventIds.length === 0) {
      return unresolved(
        "adult-entry-event-missing",
        "成年職涯路線沒有可用的第一個專屬入口事件。",
        { routeKey: route.routeKey }
      );
    }

    return deepFreeze({
      status: "resolved",
      resolved: true,
      source: {
        nodeId: snapshot.nodeId,
        chapter: snapshot.chapter,
        age: snapshot.age,
        careerExit: snapshot.careerExit
      },
      target: {
        nodeId: targetNode.nodeId,
        chapter: targetNode.chapter,
        routeKey: route.routeKey,
        entryEventId: route.exclusiveEventIds[0]
      },
      issues: []
    });
  }

  const api = Object.freeze({ resolveGraduationTransition });
  if (typeof window !== "undefined") window.GraduationTransitionResolver = api;
  if (typeof module !== "undefined" && module.exports) module.exports = api;
  return api;
})(
  typeof CareerSpineContract !== "undefined"
    ? CareerSpineContract
    : typeof require === "function"
      ? require("./career-spine-contract.js")
      : null
);

sources.career-transition-runtime-resolver.js:
var CareerTransitionRuntimeResolver = ((careerSpineContract) => {
  function clone(value) {
    if (value === undefined) return undefined;
    return JSON.parse(JSON.stringify(value));
  }

  function deepFreeze(value) {
    if (!value || typeof value !== "object" || Object.isFrozen(value)) return value;
    Object.values(value).forEach(deepFreeze);
    return Object.freeze(value);
  }

  function unresolved(code, message, details) {
    return deepFreeze({
      status: "unresolved",
      resolved: false,
      nodeId: null,
      routeKey: null,
      transitionStep: null,
      eventId: null,
      issues: [{ code, message }],
      details: details ? clone(details) : null
    });
  }

  function resolveTransitionRuntime(playerState) {
    if (!playerState || typeof playerState !== "object" || Array.isArray(playerState)) {
      return unresolved(
        "transition-runtime-state-missing",
        "Adult Transition Runtime Resolver 需要 Player 狀態物件。"
      );
    }

    if (!careerSpineContract || typeof careerSpineContract.getCareerNetwork !== "function") {
      return unresolved(
        "career-network-contract-unavailable",
        "無法取得 Architecture Sprint 4.3 的成年職涯網路契約。"
      );
    }

    let network;
    try {
      network = careerSpineContract.getCareerNetwork();
    } catch (_error) {
      return unresolved(
        "career-network-contract-read-failed",
        "成年職涯網路契約無法讀取。"
      );
    }

    const transitionNode = Array.isArray(network?.adultNodes)
      ? network.adultNodes.find(node => node.networkRole === "initial-route-and-shared-transition")
      : null;
    if (!transitionNode || typeof transitionNode.chapter !== "string") {
      return unresolved(
        "transition-runtime-node-missing",
        "成年職涯網路沒有唯一的生涯轉換期節點。"
      );
    }

    if (playerState.chapter !== transitionNode.chapter) {
      return unresolved(
        "transition-runtime-chapter-ineligible",
        "目前 chapter 不屬於生涯轉換期 Runtime Routing。",
        { chapter: playerState.chapter, expectedChapter: transitionNode.chapter }
      );
    }

    const matchingRoutes = Array.isArray(network.initialRoutes)
      ? network.initialRoutes.filter(route =>
        Array.isArray(route.careerExits) && route.careerExits.includes(playerState.careerExit)
      )
      : [];
    if (matchingRoutes.length !== 1) {
      return unresolved(
        matchingRoutes.length === 0
          ? "transition-runtime-career-exit-unmapped"
          : "transition-runtime-career-exit-ambiguous",
        matchingRoutes.length === 0
          ? "careerExit 沒有對應到合法的成年轉換路線。"
          : "careerExit 同時對應到多個成年轉換路線。",
        { careerExit: playerState.careerExit, matchingRouteCount: matchingRoutes.length }
      );
    }

    const route = matchingRoutes[0];
    const routeEventIds = []
      .concat(Array.isArray(route.exclusiveEventIds) ? route.exclusiveEventIds : [])
      .concat(Array.isArray(route.sharedEventIds) ? route.sharedEventIds : []);
    const transitionStep = playerState.transitionStep;
    if (
      !Number.isInteger(transitionStep) ||
      transitionStep < 0 ||
      transitionStep >= routeEventIds.length
    ) {
      return unresolved(
        "transition-runtime-step-invalid",
        "transitionStep 不是目前成年路線的合法事件索引。",
        { transitionStep, legalMin: 0, legalMax: routeEventIds.length - 1 }
      );
    }

    const eventId = routeEventIds[transitionStep];
    if (typeof eventId !== "string" || !eventId.trim()) {
      return unresolved(
        "transition-runtime-event-missing",
        "成年職涯網路在目前 transitionStep 沒有合法事件。",
        { routeKey: route.routeKey, transitionStep }
      );
    }

    return deepFreeze({
      status: "resolved",
      resolved: true,
      nodeId: transitionNode.nodeId,
      routeKey: route.routeKey,
      transitionStep,
      eventId,
      issues: []
    });
  }

  const api = Object.freeze({ resolveTransitionRuntime });
  if (typeof window !== "undefined") window.CareerTransitionRuntimeResolver = api;
  if (typeof module !== "undefined" && module.exports) module.exports = api;
  return api;
})(
  typeof CareerSpineContract !== "undefined"
    ? CareerSpineContract
    : typeof require === "function"
      ? require("./career-spine-contract.js")
      : null
);

