var CoachEvaluationBoundary = (() => {
  const MIN_TRUST = 0;
  const MAX_TRUST = 20;
  const FORBIDDEN_KEYS = new Set(["__proto__", "constructor", "prototype"]);
  const EVALUATION_SPECIFICATIONS = Object.freeze({
    "coach-trust-response:youth_match_entry": Object.freeze({
      eventId: "youth_match_entry",
      threshold: 3,
      matchedCategory: "supportive",
      unmatchedCategory: "standard",
      responseId: "youth_match_entry",
      routeType: "existing-narrative"
    }),
    "coach-trust-response:high_school_showcase": Object.freeze({
      eventId: "high_school_showcase",
      threshold: 8,
      matchedCategory: "early-opportunity",
      unmatchedCategory: "late-opportunity",
      responseId: "high_school_showcase",
      routeType: "existing-narrative"
    })
  });
  const SUPPORTED_EVALUATIONS = Object.freeze(
    Object.keys(EVALUATION_SPECIFICATIONS)
  );

  function isRecord(value) {
    if (value === null || typeof value !== "object" || Array.isArray(value)) {
      return false;
    }

    const objectPrototype = Object.getPrototypeOf(value);
    return objectPrototype === Object.prototype || objectPrototype === null;
  }

  function hasUnsafeStructure(value, seen = new WeakSet()) {
    if (!isRecord(value)) return false;
    if (seen.has(value)) return true;
    seen.add(value);

    return Reflect.ownKeys(value).some(key => {
      if (typeof key !== "string" || FORBIDDEN_KEYS.has(key)) return true;
      return hasUnsafeStructure(value[key], seen);
    });
  }

  function clone(value) {
    return JSON.parse(JSON.stringify(value));
  }

  function deepFreeze(value) {
    if (!value || typeof value !== "object" || Object.isFrozen(value)) {
      return value;
    }

    Object.freeze(value);
    Object.values(value).forEach(deepFreeze);
    return value;
  }

  function failure(error) {
    return { ok: false, error };
  }

  function validateExactKeys(value, allowedKeys, label) {
    const keys = Object.keys(value);
    const unknownKey = keys.find(key => !allowedKeys.includes(key));
    if (unknownKey) {
      return failure(`${label} 含有未允許欄位：${unknownKey}`);
    }

    const missingKey = allowedKeys.find(
      key => !Object.prototype.hasOwnProperty.call(value, key)
    );
    if (missingKey) {
      return failure(`${label} 缺少必要欄位：${missingKey}`);
    }

    return { ok: true };
  }

  function getCoachTrust() {
    if (
      typeof RelationshipBoundary !== "object" ||
      typeof RelationshipBoundary.getRelationship !== "function"
    ) {
      return null;
    }
    return RelationshipBoundary.getRelationship("coachTrust");
  }

  function getInputSnapshot() {
    return deepFreeze({
      relationships: {
        coachTrust: getCoachTrust()
      }
    });
  }

  function getSupportedEvaluationIds() {
    return SUPPORTED_EVALUATIONS.slice();
  }

  function isSupportedEvaluation(evaluationId) {
    return SUPPORTED_EVALUATIONS.includes(evaluationId);
  }

  function getEvaluationSpecification(evaluationId) {
    const specification = EVALUATION_SPECIFICATIONS[evaluationId];
    return specification ? deepFreeze(clone(specification)) : null;
  }

  function getRegistryMetadata() {
    return deepFreeze(
      SUPPORTED_EVALUATIONS.map(evaluationId => {
        const specification = EVALUATION_SPECIFICATIONS[evaluationId];
        return {
          evaluationId,
          owner: "CoachEvaluationBoundary",
          ownerType: "coach-evaluation",
          eventId: specification.eventId,
          responseId: specification.responseId,
          routeType: specification.routeType
        };
      })
    );
  }

  function validateCoachEvaluationRequest(request) {
    if (!isRecord(request) || hasUnsafeStructure(request)) {
      return failure("Coach Evaluation Request 必須是安全的純物件。");
    }

    const requestKeys = validateExactKeys(
      request,
      ["source", "evaluationId", "context", "expected"],
      "Coach Evaluation Request"
    );
    if (!requestKeys.ok) return requestKeys;

    if (typeof request.source !== "string" || request.source.trim() === "") {
      return failure("source 必須是非空白字串。");
    }
    if (
      typeof request.evaluationId !== "string" ||
      request.evaluationId.trim() === ""
    ) {
      return failure("evaluationId 必須是非空白字串。");
    }

    const evaluationId = request.evaluationId.trim();
    if (!isSupportedEvaluation(evaluationId)) {
      return failure(`不支援的 Coach Evaluation：${evaluationId}`);
    }
    const specification = EVALUATION_SPECIFICATIONS[evaluationId];

    if (!isRecord(request.context)) {
      return failure("context 必須是純物件。");
    }
    const contextKeys = validateExactKeys(
      request.context,
      ["eventId", "choiceIndex"],
      "context"
    );
    if (!contextKeys.ok) return contextKeys;
    if (request.context.eventId !== specification.eventId) {
      return failure(
        `eventId 必須與 ${evaluationId} 對應的 ${specification.eventId} 一致。`
      );
    }
    if (request.context.choiceIndex !== null) {
      return failure("此 Coach Response 不是 choice 觸發，choiceIndex 必須是 null。");
    }
    if (request.source.trim() !== `event:${specification.eventId}`) {
      return failure("source 必須與 context.eventId 一致。");
    }

    if (!isRecord(request.expected)) {
      return failure("expected 必須是純物件。");
    }
    const expectedKeys = validateExactKeys(
      request.expected,
      ["coachTrust"],
      "expected"
    );
    if (!expectedKeys.ok) return expectedKeys;

    const expectedTrust = request.expected.coachTrust;
    if (typeof expectedTrust !== "number" || !Number.isFinite(expectedTrust)) {
      return failure("expected.coachTrust 必須是有限數字。");
    }
    if (expectedTrust < MIN_TRUST || expectedTrust > MAX_TRUST) {
      return failure(
        `expected.coachTrust 必須介於 ${MIN_TRUST} 到 ${MAX_TRUST}。`
      );
    }

    const currentTrust = getCoachTrust();
    if (
      typeof currentTrust !== "number" ||
      !Number.isFinite(currentTrust) ||
      currentTrust < MIN_TRUST ||
      currentTrust > MAX_TRUST
    ) {
      return failure("RelationshipBoundary 的 coachTrust 不是合法正式值。");
    }
    if (currentTrust !== expectedTrust) {
      return failure(
        "expected.coachTrust 與 RelationshipBoundary 的正式值不一致。"
      );
    }

    return {
      ok: true,
      request: deepFreeze(clone({
        source: request.source.trim(),
        evaluationId,
        context: {
          eventId: request.context.eventId,
          choiceIndex: null
        },
        expected: {
          coachTrust: expectedTrust
        }
      }))
    };
  }

  function evaluateCoachResponse(request) {
    const validation = validateCoachEvaluationRequest(request);
    if (!validation.ok) return validation;

    const approved = validation.request;
    const specification =
      EVALUATION_SPECIFICATIONS[approved.evaluationId];
    const coachTrust = approved.expected.coachTrust;
    const matched = coachTrust >= specification.threshold;

    return deepFreeze({
      ok: true,
      response: {
        evaluationId: approved.evaluationId,
        category: matched
          ? specification.matchedCategory
          : specification.unmatchedCategory,
        responseId: specification.responseId,
        routeType: specification.routeType,
        matchedCondition: {
          field: "coachTrust",
          operator: matched ? ">=" : "<",
          value: specification.threshold
        }
      }
    });
  }

  const api = Object.freeze({
    getInputSnapshot,
    validateCoachEvaluationRequest,
    evaluateCoachResponse,
    getSupportedEvaluationIds,
    getEvaluationSpecification,
    getRegistryMetadata,
    getCoachTrust,
    isSupportedEvaluation
  });

  if (typeof window !== "undefined") {
    window.CoachEvaluationBoundary = api;
  }

  return api;
})();

sources.coach-response-flow.js:
var CoachResponseFlow = (() => {
  const EVENT_EVALUATION_IDS = Object.freeze({
    youth_match_entry: "coach-trust-response:youth_match_entry",
    high_school_showcase: "coach-trust-response:high_school_showcase"
  });
  const FORBIDDEN_KEYS = new Set(["__proto__", "constructor", "prototype"]);

  function isRecord(value) {
    if (value === null || typeof value !== "object" || Array.isArray(value)) {
      return false;
    }

    const objectPrototype = Object.getPrototypeOf(value);
    return objectPrototype === Object.prototype || objectPrototype === null;
  }

  function hasUnsafeStructure(value, seen = new WeakSet()) {
    if (!isRecord(value)) return false;
    if (seen.has(value)) return true;
    seen.add(value);

    return Reflect.ownKeys(value).some(key => {
      if (typeof key !== "string" || FORBIDDEN_KEYS.has(key)) return true;
      return hasUnsafeStructure(value[key], seen);
    });
  }

  function clone(value) {
    return JSON.parse(JSON.stringify(value));
  }

  function deepFreeze(value) {
    if (!value || typeof value !== "object" || Object.isFrozen(value)) {
      return value;
    }

    Object.freeze(value);
    Object.values(value).forEach(deepFreeze);
    return value;
  }

  function failure(error) {
    return { ok: false, error };
  }

  function validateExactKeys(value, allowedKeys, label) {
    const keys = Object.keys(value);
    const unknownKey = keys.find(key => !allowedKeys.includes(key));
    if (unknownKey) {
      return failure(`${label} 含有未允許欄位：${unknownKey}`);
    }

    const missingKey = allowedKeys.find(
      key => !Object.prototype.hasOwnProperty.call(value, key)
    );
    if (missingKey) {
      return failure(`${label} 缺少必要欄位：${missingKey}`);
    }

    return { ok: true };
  }

  function validateCoachResponseContext(context) {
    if (!isRecord(context) || hasUnsafeStructure(context)) {
      return failure("Coach Response Context 必須是安全的純物件。");
    }

    const contextKeys = validateExactKeys(
      context,
      ["eventId", "choiceIndex"],
      "Coach Response Context"
    );
    if (!contextKeys.ok) return contextKeys;
    const evaluationId = EVENT_EVALUATION_IDS[context.eventId];
    if (!evaluationId) {
      return failure(`尚未支援此 Coach Response event：${context.eventId}`);
    }
    if (context.choiceIndex !== null) {
      return failure("此 Coach Response 不是 choice 觸發，choiceIndex 必須是 null。");
    }

    const eventResolver = globalThis.getEvent;
    if (typeof eventResolver !== "function") {
      return failure("目前無法解析事件。");
    }
    const event = eventResolver(context.eventId);
    if (!event || typeof event.text !== "function") {
      return failure("Coach Response Context 對應的既有事件不存在。");
    }
    if (
      typeof CoachEvaluationBoundary !== "object" ||
      typeof CoachEvaluationBoundary.isSupportedEvaluation !== "function" ||
      typeof CoachEvaluationBoundary.getEvaluationSpecification !==
        "function" ||
      !CoachEvaluationBoundary.isSupportedEvaluation(evaluationId)
    ) {
      return failure("目標 Coach Evaluation 尚未獲得 Boundary 支援。");
    }
    const specification =
      CoachEvaluationBoundary.getEvaluationSpecification(evaluationId);
    if (!specification || specification.eventId !== context.eventId) {
      return failure("Coach Response event 與 evaluation mapping 不一致。");
    }

    return {
      ok: true,
      context: {
        eventId: context.eventId,
        choiceIndex: null
      }
    };
  }

  function createCoachResponseContext(eventId, choiceIndex = null) {
    const validation = validateCoachResponseContext({ eventId, choiceIndex });
    if (!validation.ok) return validation;
    return {
      ok: true,
      context: deepFreeze(clone(validation.context))
    };
  }

  function createCoachEvaluationRequest(context) {
    const validation = validateCoachResponseContext(context);
    if (!validation.ok) return validation;

    const evaluationId =
      EVENT_EVALUATION_IDS[validation.context.eventId];
    const input = CoachEvaluationBoundary.getInputSnapshot();
    const request = {
      source: `event:${validation.context.eventId}`,
      evaluationId,
      context: clone(validation.context),
      expected: {
        coachTrust: input.relationships.coachTrust
      }
    };
    const requestValidation =
      CoachEvaluationBoundary.validateCoachEvaluationRequest(request);
    if (!requestValidation.ok) return requestValidation;

    return {
      ok: true,
      request: deepFreeze(clone(requestValidation.request))
    };
  }

  function resolveCoachResponse(context) {
    const requestResult = createCoachEvaluationRequest(context);
    if (!requestResult.ok) return requestResult;
    return CoachEvaluationBoundary.evaluateCoachResponse(requestResult.request);
  }

  function applyCoachResponse(result) {
    if (!isRecord(result) || hasUnsafeStructure(result)) {
      return failure("Coach Response Result 必須是安全的純物件。");
    }
    const resultKeys = validateExactKeys(result, ["ok", "response"], "Coach Response Result");
    if (!resultKeys.ok) return resultKeys;
    if (result.ok !== true || !isRecord(result.response)) {
      return failure("Coach Response Result 尚未成功解析。");
    }

    const responseKeys = validateExactKeys(
      result.response,
      [
        "evaluationId",
        "category",
        "responseId",
        "routeType",
        "matchedCondition"
      ],
      "Coach Response"
    );
    if (!responseKeys.ok) return responseKeys;
    if (
      typeof CoachEvaluationBoundary !== "object" ||
      typeof CoachEvaluationBoundary.getEvaluationSpecification !== "function"
    ) {
      return failure("Coach Evaluation specification 無法使用。");
    }
    const specification =
      CoachEvaluationBoundary.getEvaluationSpecification(
        result.response.evaluationId
      );
    if (
      !specification ||
      result.response.responseId !== specification.responseId ||
      result.response.routeType !== specification.routeType
    ) {
      return failure("Coach Response 不符合本次既有 narrative hook。");
    }
    if (!isRecord(result.response.matchedCondition)) {
      return failure("Coach Response 缺少既有門檻資訊。");
    }
    const conditionKeys = validateExactKeys(
      result.response.matchedCondition,
      ["field", "operator", "value"],
      "matchedCondition"
    );
    if (!conditionKeys.ok) return conditionKeys;
    const matched =
      result.response.category === specification.matchedCategory;
    const unmatched =
      result.response.category === specification.unmatchedCategory;
    if (!matched && !unmatched) {
      return failure("Coach Response category 不符合 evaluation specification。");
    }
    const expectedOperator = matched ? ">=" : "<";
    if (
      result.response.matchedCondition.field !== "coachTrust" ||
      result.response.matchedCondition.operator !== expectedOperator ||
      result.response.matchedCondition.value !== specification.threshold
    ) {
      return failure("Coach Response 沒有沿用既有 coachTrust 門檻。");
    }

    return deepFreeze({
      ok: true,
      responseId: result.response.responseId,
      category: result.response.category,
      routeType: result.response.routeType
    });
  }

  function getSupportedEventMap() {
    return deepFreeze(clone(EVENT_EVALUATION_IDS));
  }

  const api = Object.freeze({
    createCoachResponseContext,
    validateCoachResponseContext,
    createCoachEvaluationRequest,
    resolveCoachResponse,
    applyCoachResponse,
    getSupportedEventMap
  });

  if (typeof window !== "undefined") {
    window.CoachResponseFlow = api;
  }

  return api;
})();

