      if (!OutcomeMapping) throw new Error("Physical BIP requires BattedBallOutcomeMapping");
      const official = OutcomeMapping.resolveOfficialBallInPlayOutcome({
        physicalTruth,
        defenseOutcome: physicalOutcome?.result ? { ...physicalOutcome, authority: physicalOutcome.authority || "physicalOutcomeResolver", settled: true, physicalIdentity: physicalTruth.identity } : physicalOutcome,
        rolls: { ...options.mappingRolls, ...(options.outcomeRoll !== undefined && options.mappingRolls?.hit === undefined ? { hit: options.outcomeRoll } : {}) }
      });
      outcome = deepFreeze({ ...official, adapterAuthority: official.authority,
        contactQuality: physicalTruth.executionEvidence.continuousContactScore, resolvedContact: official.trace.hitScore });
    } else outcome = resolveLegacyBallInPlayOutcome({ ...state, swingIntent }, pitch, abilities, recognition, null, options.outcomeRoll);
    return deepFreeze({ physicalTruth, outcome });
  }

  function summarizeQualities(state) {
    const history = state.pitchHistory || [];
    const decisionFit = history.map(item => {
      const perceivedPitchClass = item.recognition?.perceivedPitchClass || item.pitch?.pitchLocationClass;
      const profileState = { selectionProfile: item.selectionProfile || state.selectionProfile, strikes: Number(item.countBefore?.strikes) || 0 };
      const tendency = getSwingTendency(profileState, { perceivedPitchClass }).tendency;
      return item.action === "swing" ? tendency : 1 - tendency;
    });
    const decisionRatio = decisionFit.length ? decisionFit.reduce((sum, value) => sum + value, 0) / decisionFit.length : 0;
    const decisionQuality = decisionRatio >= 0.72 ? "strong" : decisionRatio >= 0.52 ? "acceptable" : decisionRatio >= 0.35 ? "questionable" : "poor";
    const execution = state.swingExecutionSummary;
    const executionQuality = execution.ballsInPlay > 0
      ? execution.hardContacts > 0 ? "strong" : "normal"
      : execution.swings > 0 && execution.whiffs / execution.swings <= 0.34 ? "normal" : "weak";
    return { decisionQuality, executionQuality };
  }

  function assertPitchResultIntegrity(event, terminalState = null) {
    if (!event) return true;
    const result = event.pitchResult;
    const contact = event.contact;
    if (result === "calledStrike" && (event.action !== "take" || contact !== null)) throw new Error("calledStrike requires take without contact");
    if (result === "ball" && (event.action !== "take" || contact !== null)) throw new Error("ball requires take without contact");
    if (result === "swingingStrike" && (event.action !== "swing" || contact !== false)) throw new Error("swingingStrike requires a missed swing");
    if (["foul", "ballInPlay"].includes(result) && (event.action !== "swing" || contact !== true)) throw new Error(`${result} requires swing and contact`);
    if (terminalState?.result === "walk" && !(event.pitchResult === "ball" && Number(terminalState.balls) >= 4)) throw new Error("walk must terminate on ball four");
    if (terminalState?.result === "strikeout" && (!['calledStrike', 'swingingStrike'].includes(event.pitchResult) || Number(terminalState.strikes) < 3)) throw new Error("strikeout must terminate on strike three");
    if (["out", "productiveOut", "single", "double", "triple", "homeRun"].includes(terminalState?.result) && event.pitchResult !== "ballInPlay") throw new Error("ball-in-play PA result requires terminal ballInPlay pitch");
    return true;
  }

  function resolveNextPitch(inputState, abilities = {}, options = {}) {
    let state = normalizePlateAppearanceState(inputState);
    if (!state || state.completed || state.awaitingDefense) return deepFreeze({ state, event: null, duplicate: Boolean(state?.completed), awaitingDefense: Boolean(state?.awaitingDefense) });
    if (!state.pendingPitch) state = prepareNextPitch(state, options.pitch || null);
    const pitch = state.pendingPitch;
    const countBefore = { balls: state.balls, strikes: state.strikes };
    const recognition = options.recognition ? deepFreeze(clone(options.recognition)) : getRecognitionResult(state, pitch, abilities, options.recognitionRoll);
    const swingProfile = getSwingTendency(state, recognition);
    const decisionRoll = Number.isFinite(Number(options.decisionRoll)) ? clamp(options.decisionRoll)
      : deterministicUnit(state.paIdentity, `swing-decision|${state.pitchNumber + 1}`);
    const safetyPitch = state.pitchNumber + 1 >= ABSOLUTE_PITCH_SAFETY_CAP;
    const explicitDecision = PLATE_DECISION_ROUTES[options.decisionRoute] ? options.decisionRoute : "";
    const decisionProfile = explicitDecision ? PLATE_DECISION_ROUTES[explicitDecision] : null;
    let action = safetyPitch ? "swing" : decisionProfile ? decisionProfile.action : decisionRoll < swingProfile.tendency ? "swing" : "take";
    const pitchSwingIntent = decisionProfile?.swingIntent || state.swingIntent;
    let pitchResult = "";
    let paResult = "";
    let contactQuality = null;
    let battedBallPhysicalTruth = null;
    let officialBallInPlayOutcome = null;
    let contact = null;
    const recognitionSummary = clone(state.recognitionSummary);
    recognitionSummary[recognition.correct ? "correct" : "misread"] += 1;
    if (recognition.correct && pitch.pitchLocationClass === "chasePitch") recognitionSummary.chaseRecognized += 1;
    if (recognition.correct && pitch.pitchLocationClass === "hitterPitch") recognitionSummary.hitterPitchRecognized += 1;
    const swingExecutionSummary = clone(state.swingExecutionSummary);
    let balls = state.balls;
    let strikes = state.strikes;
    if (safetyPitch) {
      pitchResult = "ballInPlay";
      contact = true;
      swingExecutionSummary.swings += 1;
      swingExecutionSummary.ballsInPlay += 1;
      const bip = resolveFairContactBallInPlay(state, pitch, abilities, recognition, { ...options, swingIntent: pitchSwingIntent });
      paResult = bip.outcome.result;
      contactQuality = bip.outcome.contactQuality;
      battedBallPhysicalTruth = bip.physicalTruth;
      officialBallInPlayOutcome = bip.outcome;
      if (bip.outcome.contactQuality >= 0.72) swingExecutionSummary.hardContacts += 1;
    } else if (action === "take") {
      swingExecutionSummary.takes += 1;
      if (pitch.strike) {
        pitchResult = "calledStrike";
        strikes += 1;
      } else {
        pitchResult = "ball";
        balls += 1;
      }
    } else {
      swingExecutionSummary.swings += 1;
      const executionProfile = explicitDecision ? getSwingExecutionProfile(state, pitch, abilities, recognition, explicitDecision) : null;
      const contactProbability = getContactProbability(state, pitch, abilities, recognition, pitchSwingIntent);
      const contactRoll = Number.isFinite(Number(options.contactRoll)) ? clamp(options.contactRoll)
        : deterministicUnit(state.paIdentity, `contact|${state.pitchNumber + 1}`);
      const timingRoll = Number.isFinite(Number(options.timingRoll)) ? clamp(options.timingRoll) : contactRoll;
      const batToBallRoll = Number.isFinite(Number(options.batToBallRoll)) ? clamp(options.batToBallRoll) : contactRoll;
      const executionContact = executionProfile
        ? timingRoll <= executionProfile.timingWindow && batToBallRoll <= executionProfile.batToBallWindow
        : contactRoll <= contactProbability;
      if (!executionContact) {
        pitchResult = "swingingStrike";
        contact = false;
        swingExecutionSummary.whiffs += 1;
        strikes += 1;
      } else {
        const foulRate = pitchSwingIntent === "contact" ? 0.36 : pitchSwingIntent === "power" ? 0.18 : 0.25;
        const foulRoll = Number.isFinite(Number(options.foulRoll)) ? clamp(options.foulRoll)
          : deterministicUnit(state.paIdentity, `foul|${state.pitchNumber + 1}`);
        if (foulRoll < foulRate) {
          pitchResult = "foul";
          contact = true;
          swingExecutionSummary.fouls += 1;
          if (strikes < 2) strikes += 1;
        } else {
          pitchResult = "ballInPlay";
          contact = true;
          swingExecutionSummary.ballsInPlay += 1;
          const bip = resolveFairContactBallInPlay(state, pitch, abilities, recognition, { ...options, swingIntent: pitchSwingIntent });
          paResult = bip.outcome.result;
          contactQuality = bip.outcome.contactQuality;
          battedBallPhysicalTruth = bip.physicalTruth;
          officialBallInPlayOutcome = bip.outcome;
          if (bip.outcome.contactQuality >= 0.72) swingExecutionSummary.hardContacts += 1;
        }
      }
    }
    if (!paResult && balls >= 4) paResult = "walk";
    if (!paResult && strikes >= 3) paResult = "strikeout";
    const safetyFallbackUsed = safetyPitch;
    const pitchNumber = state.pitchNumber + 1;
    const event = {
      pitchNumber,
      pitch,
      recognition,
      selectionProfile: state.selectionProfile,
      swingIntent: pitchSwingIntent,
      plateDecision: explicitDecision || null,
      protectAdjusted: swingProfile.protectAdjusted,
      swingTendency: swingProfile.tendency,
      attackWindow: swingProfile.attackWindow,
      swingDecisionAuthority: swingProfile.semanticAuthority,
      action,
      pitchResult,
      contact,
      contactQuality,
      battedBallPhysicalTruth,
      officialBallInPlayOutcome,
      countBefore,
      countAfter: { balls: Math.min(4, balls), strikes: Math.min(3, strikes) },
      paResult
    };
    if (action === "swing") {
      const profile = getSwingExecutionProfile(state, pitch, abilities, recognition, explicitDecision || (pitchSwingIntent === "power" ? "powerSwing" : "contactSwing"));
      event.executionEvidence = {
        timing: { window: profile.timingWindow, roll: Number.isFinite(Number(options.timingRoll)) ? clamp(options.timingRoll) : Number.isFinite(Number(options.contactRoll)) ? clamp(options.contactRoll) : deterministicUnit(state.paIdentity, `contact|${state.pitchNumber + 1}`) },
        batToBall: { window: profile.batToBallWindow, roll: Number.isFinite(Number(options.batToBallRoll)) ? clamp(options.batToBallRoll) : Number.isFinite(Number(options.contactRoll)) ? clamp(options.contactRoll) : deterministicUnit(state.paIdentity, `contact|${state.pitchNumber + 1}`) },
        contactQuality: { damageCeiling: profile.damageCeiling, realized: contact === true ? contactQuality : null },
        pitchChallenge: profile.challenges
      };
    }
    const tacticalFeedback = PitcherCatcherTacticalIntegration
      ? PitcherCatcherTacticalIntegration.recordPitchTacticalFeedback(pitch.pitchTacticalState, event) : null;
    if (tacticalFeedback) event.tacticalFeedback = clone(tacticalFeedback);
    const next = {
      ...clone(state), balls: Math.min(4, balls), strikes: Math.min(3, strikes), pitchNumber,
      pendingPitch: null, pitchHistory: [...state.pitchHistory, event], completed: Boolean(paResult), result: paResult,
      tacticalSequenceHistory: tacticalFeedback
        ? [...(state.tacticalSequenceHistory || []), clone(tacticalFeedback)].slice(-6)
        : clone(state.tacticalSequenceHistory || []),
      battedBallPhysicalTruth: battedBallPhysicalTruth || state.battedBallPhysicalTruth,
      officialBallInPlayOutcome: officialBallInPlayOutcome || state.officialBallInPlayOutcome,
      safetyFallbackUsed: state.safetyFallbackUsed || safetyFallbackUsed, recognitionSummary, swingExecutionSummary
    };
    const qualities = summarizeQualities(next);
    next.decisionQuality = qualities.decisionQuality;
    next.executionQuality = qualities.executionQuality;
    assertPitchResultIntegrity(event, next.completed ? next : null);
    return deepFreeze({ state: createPlateAppearanceState(next), event: deepFreeze(clone(event)), duplicate: false });
  }

  function simulatePlateAppearance(input = {}) {
    let state = input.state ? normalizePlateAppearanceState(input.state) : createPlateAppearanceState(input);
    const pitchSequence = Array.isArray(input.pitchSequence) ? input.pitchSequence : [];
    const pitchOptions = Array.isArray(input.pitchOptions) ? input.pitchOptions : [];
    let safety = 0;
    while (!state.completed && !state.awaitingDefense && safety < ABSOLUTE_PITCH_SAFETY_CAP) {
      const options = { ...(pitchOptions[safety] || {}) };
      if (pitchSequence[safety]) options.pitch = pitchSequence[safety];
      state = resolveNextPitch(state, input.abilities || {}, options).state;
      safety += 1;
    }
    return state;
  }

  function getPitchExecutionTrace(event = {}) {
    const pitch = event.pitch || {};
    return deepFreeze({ pitchIdentity: pitch.pitchId, pitchIntent: clone(pitch.pitchIntent || null),
      targetIntent: clone(pitch.targetIntent || null), targetSource: pitch.locationRealization?.targetSource || "legacyLocationFallback",
      command: pitch.controlRealization?.control ?? null, actualPitchClass: pitch.pitchLocationClass,
      actualLocation: pitch.location, targetError: pitch.locationRealization?.targetError ?? null,
      executionClassification: pitch.locationRealization?.executionClassification || "unmeasured",
      recognition: clone(event.recognition || null), batterResponse: event.action || null, pitchResult: event.pitchResult || null });
  }

  function markResultApplied(state) {
    const normalized = normalizePlateAppearanceState(state);
    return normalized ? createPlateAppearanceState({ ...clone(normalized), resultApplied: true }) : null;
  }

  return deepFreeze({
    VERSION,
    PITCH_SEED_NAMESPACE,
    ABSOLUTE_PITCH_SAFETY_CAP,
    PITCH_CLASSES,
    PITCH_CLASS_PROFILES,
    APPROACH_PACKAGES,
    PLATE_DECISION_ROUTES,
    ATTACK_WINDOWS,
    SWING_TENDENCIES,
    stableHash,
    deterministicUnit,
    normalizeApproachPackage,
    createPlateAppearanceIdentity,
    createPlateAppearanceState,
    normalizePlateAppearanceState,
    generatePitchOpportunity,
    prepareNextPitch,
    getPitchExecutionTrace,
    normalizeTargetIntent,
    decodePitchLocation,
    getPitchVelocityBaseline,
    resolvePitchLocation,
    getRecognitionScore,
    getRecognitionResult,
    getSwingTendency,
    getContactProbability,
    getSwingExecutionProfile,
    summarizeQualities,
    resolveLegacyBallInPlayOutcome,
    resolveFairContactBallInPlay,
    assertPitchResultIntegrity,
    resolveNextPitch,
    simulatePlateAppearance,
    markResultApplied
  });
});

sources.offensive-tactical-action.js:
(function (root, factory) {
  const api = factory();
  root.OffensiveTacticalAction = api;
  if (typeof module === "object" && module.exports) module.exports = api;
})(typeof globalThis !== "undefined" ? globalThis : this, function () {
  "use strict";

  const VERSION = "offensive-tactical-action-v1";
  const PHASES = Object.freeze(["prePitch", "delivery", "postRelease", "lateReveal"]);

  function clone(value) { return value === undefined ? undefined : JSON.parse(JSON.stringify(value)); }
  function deepFreeze(value) {
    if (!value || typeof value !== "object" || Object.isFrozen(value)) return value;
    Object.values(value).forEach(deepFreeze);
    return Object.freeze(value);
  }
  function event(id, type, timing) {
    return { id, type, timing, actor: "batter", salience: "high" };
  }
  function planFor(action, identity) {
    if (action === "sacrificeBunt") return {
      batterCommitment: "bunt", runnerCommitment: "conditionalAdvance", revealTiming: "early",
      observableEventPlan: [event(`${identity}|bunt-reveal-early`, "buntReveal", "prePitch")]
    };
    if (action === "surpriseBunt") return {
      batterCommitment: "bunt", runnerCommitment: "reactive", revealTiming: "late",
      observableEventPlan: [event(`${identity}|bunt-reveal-late`, "lateBuntReveal", "lateReveal")]
    };
    return { batterCommitment: "standard", runnerCommitment: "noSpecialTacticalCommitment", revealTiming: "none", observableEventPlan: [] };
  }
  function phaseIndex(phase) { return Math.max(0, PHASES.indexOf(phase)); }
  function createTacticalActionState(decision = {}) {
    const selected = ["standardAttack", "sacrificeBunt", "surpriseBunt"].includes(decision.selectedAction) ? decision.selectedAction : "standardAttack";
    const identity = decision.identity || "tactical-pa";
    const assignment = planFor(selected, identity);
    const initialPhase = "prePitch";
    const emitted = assignment.observableEventPlan.filter(item => phaseIndex(item.timing) <= phaseIndex(initialPhase));
    return deepFreeze({
      version: VERSION,
      identity,
      selectedTacticalAction: selected,
      batterCommitment: assignment.batterCommitment,
      runnerCommitment: assignment.runnerCommitment,
      revealTiming: assignment.revealTiming,
      currentPhase: initialPhase,
      observableEventPlan: clone(assignment.observableEventPlan),
      observableEvents: clone(emitted),
      emittedEventIds: emitted.map(item => item.id),
      executionDeferred: true
    });
  }
  function normalizeTacticalActionState(saved) {
    if (!saved || typeof saved !== "object") return null;
    const state = createTacticalActionState({ identity: saved.identity, selectedAction: saved.selectedTacticalAction });
    const emittedEventIds = Array.isArray(saved.emittedEventIds) ? saved.emittedEventIds.slice() : [];
    const observableEvents = state.observableEventPlan.filter(item => emittedEventIds.includes(item.id));
    return deepFreeze({ ...clone(state), currentPhase: PHASES.includes(saved.currentPhase) ? saved.currentPhase : "prePitch", observableEvents, emittedEventIds });
  }
  function advanceTacticalReveal(saved, phase) {
    const state = normalizeTacticalActionState(saved);
    if (!state || !PHASES.includes(phase) || phaseIndex(phase) < phaseIndex(state.currentPhase)) return state;
    const emittedEventIds = state.emittedEventIds.slice();
    const observableEvents = state.observableEvents.map(clone);
    state.observableEventPlan.forEach(item => {
      if (phaseIndex(item.timing) <= phaseIndex(phase) && !emittedEventIds.includes(item.id)) {
        emittedEventIds.push(item.id);
        observableEvents.push(clone(item));
      }
    });
    return deepFreeze({ ...clone(state), currentPhase: phase, observableEvents, emittedEventIds });
  }
  function getObservableTacticalEvents(saved) {
    return normalizeTacticalActionState(saved)?.observableEvents || deepFreeze([]);
  }
  function formatObservableTacticalInformation(observableEvents = []) {
    return deepFreeze((Array.isArray(observableEvents) ? observableEvents : []).map(item => {
      if (item.type === "buntReveal") return "打者提早擺出短打姿勢。";
      if (item.type === "lateBuntReveal") return "打者突然轉棒準備觸擊。";
      return "";
    }).filter(Boolean));
  }

  return deepFreeze({ VERSION, PHASES, createTacticalActionState, normalizeTacticalActionState, advanceTacticalReveal, getObservableTacticalEvents, formatObservableTacticalInformation });
});

sources.offensive-tactical-decision.js:
(function (root, factory) {
  const opportunity = root.OffensiveTacticalOpportunity || (typeof module === "object" && module.exports && typeof require === "function" ? require("./offensive-tactical-opportunity.js") : null);
  const api = factory(opportunity);
  root.OffensiveTacticalDecision = api;
  if (typeof module === "object" && module.exports) module.exports = api;
})(typeof globalThis !== "undefined" ? globalThis : this, function (OffensiveTacticalOpportunity) {
  "use strict";

  const VERSION = "offensive-tactical-decision-v1";
  const RNG_NAMESPACE = "offensive-tactical-decision-v1";
  const PROFILE_AXES = Object.freeze(["outPreservation", "pressureCreation", "variancePreference", "coordinationTrust", "informationExploitation"]);
  const DEFAULT_PROFILE = Object.freeze({ outPreservation: 0.55, pressureCreation: 0.5, variancePreference: 0.45, coordinationTrust: 0.5, informationExploitation: 0.5 });
  const ALLOWED_EVIDENCE_TYPES = Object.freeze(["previousBuntDefenseResponse", "recentDefensiveChargeTiming"]);

  function clone(value) { return value === undefined ? undefined : JSON.parse(JSON.stringify(value)); }
  function deepFreeze(value) {
    if (!value || typeof value !== "object" || Object.isFrozen(value)) return value;
    Object.values(value).forEach(deepFreeze);
    return Object.freeze(value);
  }
  function clamp(value, minimum = 0, maximum = 1, fallback = minimum) {
    const numeric = Number(value);
    return Math.max(minimum, Math.min(maximum, Number.isFinite(numeric) ? numeric : fallback));
  }
  function round(value, digits = 4) {
    const scale = 10 ** digits;
    return Math.round((Number(value) || 0) * scale) / scale;
  }
  function stableHash(value) {
    const text = String(value ?? "");
    let hash = 2166136261;
    for (let index = 0; index < text.length; index += 1) {
      hash ^= text.charCodeAt(index);
      hash = Math.imul(hash, 16777619);
    }
    return hash >>> 0;
  }
  function deterministicUnit(identity, label = "selection") {
    return stableHash(`${RNG_NAMESPACE}|${identity}|${label}`) / 4294967296;
  }
  function normalizeProfile(input = {}) {
    return deepFreeze(Object.fromEntries(PROFILE_AXES.map(axis => [axis, clamp(input[axis], 0, 1, DEFAULT_PROFILE[axis])])));
  }
  function createProvisionalPlayerFit(input = {}) {
    const batting = clamp((Number(input.batting) || 0) / 20);
    const baseRunning = clamp((Number(input.baseRunning) || 0) / 20);
    const baseballIQ = clamp((Number(input.baseballIQ) || 0) / 20);
    const ballSense = clamp((Number(input.ballSense) || 0) / 20);
    return deepFreeze({
      version: "provisional-existing-capability-adapter-v1",
      standardAttack: round(0.35 + batting * 0.45 + ballSense * 0.2),
      sacrificeBunt: round(0.28 + baseballIQ * 0.4 + baseRunning * 0.2 + ballSense * 0.12),
      surpriseBunt: round(0.25 + baseRunning * 0.3 + baseballIQ * 0.25 + ballSense * 0.2)
    });
  }
  function sanitizeRecentObservableEvidence(input) {
    return (Array.isArray(input) ? input : []).filter(item => item && ALLOWED_EVIDENCE_TYPES.includes(item.type)).slice(-6).map(item => ({
      type: item.type,
      value: typeof item.value === "string" ? item.value : ""
    }));
  }
  function situationValue(action, context) {
    const hasRunner = context.runners.some(Boolean);
    const scoringPosition = Boolean(context.runners[1] || context.runners[2]);
    if (action === "standardAttack") return 0.58 + (context.outs >= 2 ? 0.16 : 0) + (context.scoreDifference < 0 ? 0.08 : 0);
    if (action === "sacrificeBunt") return 0.38 + (hasRunner ? 0.22 : 0) + (scoringPosition ? 0.1 : 0) - context.outs * 0.08;
    if (action === "surpriseBunt") return 0.34 + (context.outs >= 2 ? 0.08 : 0) + (!hasRunner ? 0.08 : 0);
    return 0;
  }
  function profileValue(action, profile) {
    if (action === "standardAttack") return profile.outPreservation * 0.24 - profile.variancePreference * 0.05;
    if (action === "sacrificeBunt") return profile.pressureCreation * 0.22 + profile.coordinationTrust * 0.2 - profile.outPreservation * 0.12;
    if (action === "surpriseBunt") return profile.informationExploitation * 0.28 + profile.variancePreference * 0.18 + profile.pressureCreation * 0.1;
    return 0;
  }
  function evidenceValue(action, evidence) {
    return evidence.reduce((total, item) => {
      if (item.type === "recentDefensiveChargeTiming" && item.value === "late" && action === "surpriseBunt") return total + 0.12;
      if (item.type === "previousBuntDefenseResponse" && item.value === "earlyCharge" && action === "standardAttack") return total + 0.08;
      if (item.type === "previousBuntDefenseResponse" && item.value === "earlyCharge" && action === "surpriseBunt") return total - 0.06;
      return total;
    }, 0);
  }
  function evaluateCandidates(opportunity, profile, playerFit, evidence) {
    const evaluations = opportunity.candidateActions.map(action => {
      const situation = situationValue(action, opportunity.context);
      const coachProfile = profileValue(action, profile);
      const fit = ((playerFit[action] ?? 0.5) - 0.5) * 0.28;
      const observedEvidence = evidenceValue(action, evidence);
      const utility = round(situation + coachProfile + fit + observedEvidence);
      return { action, situationValue: round(situation), coachProfileValue: round(coachProfile), provisionalPlayerFitValue: round(fit), recentObservableEvidenceValue: round(observedEvidence), utility };
    });
    const exponentials = evaluations.map(item => Math.exp(item.utility * 2));
    const total = exponentials.reduce((sum, value) => sum + value, 0) || 1;
    return evaluations.map((item, index) => ({ ...item, weight: round(exponentials[index] / total, 6) }));
  }
  function selectWeighted(evaluations, roll) {
    let cursor = 0;
    for (const evaluation of evaluations) {
      cursor += evaluation.weight;
      if (roll < cursor) return evaluation.action;
    }
    return evaluations.at(-1)?.action || "standardAttack";
  }
  function resolveTacticalDecision(input = {}) {
    if (!OffensiveTacticalOpportunity) throw new Error("OffensiveTacticalOpportunity is required");
    const opportunity = input.opportunity?.version ? input.opportunity : OffensiveTacticalOpportunity.resolveTacticalOpportunity(input.context || {});
    const profile = normalizeProfile(input.tacticalProfile || {});
    const playerFit = input.playerFit?.version ? deepFreeze(clone(input.playerFit)) : createProvisionalPlayerFit(input.playerCapabilities || {});
    const recentObservableEvidence = sanitizeRecentObservableEvidence(input.recentObservableEvidence);
    const candidates = opportunity.candidateActions.length ? opportunity.candidateActions : ["standardAttack"];
    const safeOpportunity = { ...opportunity, candidateActions: candidates };
    const evaluations = evaluateCandidates(safeOpportunity, profile, playerFit, recentObservableEvidence);
    const identity = String(input.identity || [opportunity.context.batterId || "batter", opportunity.context.inning, opportunity.context.half, opportunity.context.outs, opportunity.context.runners.map(Boolean).join("")].join("|"));
    const selectionRoll = deterministicUnit(`${input.seed ?? "default"}|${identity}`);
    const selectedAction = selectWeighted(evaluations, selectionRoll);
    return deepFreeze({
      version: VERSION,
      identity,
      rngNamespace: RNG_NAMESPACE,
      selectedAction,
      distribution: Object.fromEntries(evaluations.map(item => [item.action, item.weight])),
      debugTrace: {
        tacticalContext: clone(opportunity.context),
        opportunityEntries: clone(opportunity.entries),
        candidateActions: candidates.slice(),
        provisionalTacticalProfile: clone(profile),
        provisionalPlayerFit: clone(playerFit),
        recentObservableEvidence: clone(recentObservableEvidence),
        subjectiveEvaluations: clone(evaluations),
        selectionRoll,
        selectedTacticalAction: selectedAction,
        inputBoundary: ["currentGameContext", "provisionalTacticalProfile", "existingPlayerCapabilities", "recentObservableDefensiveResponse"]
