  const PRODUCTION_ACTIVE_ACTIONS = Object.freeze(["standardAttack", "sacrificeBunt", "surpriseBunt"]);
  const STATUSES = Object.freeze({ available: "available", irrelevant: "irrelevant", unsupported: "unsupported" });

