    return count && Number.isInteger(count.balls) && count.balls >= 0 && count.balls <= (terminal ? 4 : 3)
      && Number.isInteger(count.strikes) && count.strikes >= 0 && count.strikes <= (terminal ? 3 : 2);
  }
