    ["takePattern", ["TAKE_PATTERN_PRESENT", "TAKE_PATTERN_STRONG"]],
    ["calledStrikePattern", ["CALLED_STRIKE_PATTERN_PRESENT"]],
    ["chasePattern", ["CHASE_PATTERN_PRESENT"]],
