  const DEFERRED_INTERPRETATIONS = Object.freeze(["REPEATED_TARGET_HITS", "VELOCITY_DOWN_PATTERN", "LOCATION_MISS_PUNISHED"]);

  function freeze(value) {
    if (value && typeof value === "object" && !Object.isFrozen(value)) {
