  function normalizeSequenceHistory(history) {
    return deepFreeze((Array.isArray(history) ? history : []).map(normalizeFeedback).filter(Boolean).slice(-HISTORY_LIMIT));
  }

  function summarizePreviousSwingResponse(previous) {
