function dedupePositionDecisionChoices(choices = []) {
  const seen = new Set();
  return choices.filter(choice => {
    const key = getPositionChoiceCommitmentKey(choice);
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

