function renderHighSchoolPlateDecisionContext(match) {
  if (typeof PlateDecisionFoundation === "undefined") return "";
  const context = PlateDecisionFoundation.getPlayerFacingContext(match?.activeSituation);
  if (!context) return "";
  const stateLabels = { accurate: "看得清楚", partial: "只掌握部分軌跡", misread: "判讀仍有疑點", late: "判讀偏晚" };
  return `<section class="match-batter-read plate-decision-context" aria-labelledby="plateDecisionContextTitle">
    <small id="plateDecisionContextTitle">第 ${context.pitchIndex} 球・你的即時判讀</small>
    <div class="match-batter-read__item"><strong>來球印象</strong><p>${escapeHtml(context.perceivedPitch.locationCue)}，${escapeHtml(context.perceivedPitch.velocityCue)}；${escapeHtml(context.perceivedPitch.movementCue)}。</p></div>
    <div class="match-batter-read__item"><strong>你的判斷</strong><p>${escapeHtml(context.perceivedPitch.zoneCue)}。${escapeHtml(stateLabels[context.recognitionState] || "正在辨識")}</p></div>
  </section>`;
}

function getHighSchoolPlateDecisionChoices(match) {
  if (typeof PlateDecisionFoundation === "undefined") return [];
  const context = PlateDecisionFoundation.getPlayerFacingContext(match?.activeSituation);
  const momentId = getHighSchoolYearOneMomentId(match);
  if (!context || !momentId) return [];
  return context.routes.map(route => Object.freeze({
    text: route.text,
    matchDecision: route.matchDecision,
    matchMomentId: momentId,
    strategicTradeoff: route.tradeoff,
    plateDecisionRoute: route.routeId
  }));
}

function renderHighSchoolBatterAnticipationPanel(match) {
  if (typeof BatterAnticipation === "undefined" || !match?.batterAnticipationState) return "";
  const presentation = BatterAnticipation.createPrePAPresentation(match.batterAnticipationState);
  const observationHtml = presentation.observationLines.map(line => `<p>${escapeHtml(line)}</p>`).join("");
  return `<section class="match-batter-read" aria-labelledby="batterReadTitle">
    <small id="batterReadTitle">打席判讀</small>
    <div class="match-batter-read__item"><strong>觀察</strong>${observationHtml}</div>
    <div class="match-batter-read__item"><strong>你的預判</strong><p>${escapeHtml(presentation.anticipationText)}</p></div>
    <div class="match-batter-read__confidence"><strong>判斷把握</strong><span>${escapeHtml(presentation.confidenceText)}</span></div>
  </section>`;
}

function buildOffensiveDecisionChoices(match) {
  const context = analyzeHighSchoolOffensiveDecisionContext(match);
  const momentId = getHighSchoolYearOneMomentId(match);
  if (!momentId || match?.currentDomain === "defense") return [];
  const make = ({ text, matchDecision, objective, approach, route, riskProfile, requirements = [], executionText }) => Object.freeze({
    ...OffensivePlateApproach.normalizeApproachPackage(approach),
    text,
    matchDecision,
    matchMomentId: momentId,
    objective,
    approach,
    action: approach,
    route,
    riskProfile,
    risk: riskProfile,
    requirements: Object.freeze(requirements.slice()),
    executionOnly: false,
    executionText
  });
  const attackTask = context.scoreDifference === -1 ? "直接挑戰追平機會"
    : context.scoreDifference < -1 ? "嘗試長打縮小差距"
      : context.scoreDifference === 0 ? "直接挑戰超前機會"
        : context.hasRunner ? "挑戰外野空檔增加保險分" : "挑戰外野空檔擴大領先";
  const choices = [
    make({
      text: `搶第一顆可攻擊球，${attackTask}`,
      matchDecision: "attack",
      objective: "createExtraBaseHit",
      approach: "aggressiveEarlySwing",
      route: "attackPitchToGap",
      riskProfile: "high",
      executionText: "你提早備妥揮棒，鎖定第一顆進入可攻擊區域的球。"
    }),
    make({
      text: "縮小攻擊區，盡量放掉邊角球，只積極處理真正進入甜蜜區的球",
      matchDecision: "zone",
      objective: "reachBase",
      approach: "patientSelection",
      route: "selectivePlateAppearance",
      riskProfile: "low",
      executionText: "你收窄攻擊區，但仍準備攻擊真正進入甜蜜點的球。"
    })
  ];
  if (!context.hasRunner) {
    choices.push(make({
      text: "縮短揮棒，提高把球確實打進場內的機會",
      matchDecision: "advance",
      objective: "putBallInPlay",
      approach: "compactContact",
      route: "contactFirst",
      riskProfile: "medium",
      executionText: "你縮短揮棒軌跡，把重點放在確實擊中來球。"
    }));
  } else if (context.twoOuts && context.scoringPosition) {
    choices.push(make({
      text: "縮短揮棒，爭取用安打送回得分位置上的跑者",
      matchDecision: "advance",
      objective: "scoreRunner",
      approach: "compactLineDrive",
      route: "contactForRun",
      riskProfile: "medium",
      requirements: ["runnerInScoringPosition"],
      executionText: "兩出局後不能用出局交換推進；你縮短揮棒，尋找能穿過守備的擊球。"
    }));
  } else if (context.twoOuts) {
    choices.push(make({
      text: "縮短揮棒，先把攻勢延續到下一棒",
      matchDecision: "advance",
      objective: "reachBase",
      approach: "compactContact",
      route: "extendInning",
      riskProfile: "medium",
      executionText: "兩出局後你不以犧牲推進為目標，而是縮短揮棒爭取上壘。"
    }));
  } else if (context.third) {
    choices.push(make({
      text: "縮短揮棒，讓三壘跑者有回本壘的機會",
      matchDecision: "advance",
      objective: "scoreRunner",
      approach: "compactContact",
      route: "contactForRun",
      riskProfile: "medium",
      requirements: ["runnerOnThird", "fewerThanTwoOuts"],
      executionText: "你縮短揮棒，嘗試用有效擊球送回三壘跑者。"
    }));
  } else {
    choices.push(make({
      text: context.second ? "縮短揮棒，把二壘跑者向下一個壘包推進" : "縮短揮棒，爭取把一壘跑者送進得分位置",
      matchDecision: "advance",
      objective: "advanceRunner",
      approach: "compactContact",
      route: "advanceExistingRunner",
      riskProfile: "medium",
      requirements: context.second ? ["runnerOnSecond", "fewerThanTwoOuts"] : ["runnerOnFirst", "fewerThanTwoOuts"],
      executionText: "你縮短揮棒軌跡，讓擊球方向服務眼前真實存在的跑者。"
    }));
  }
  return choices;
}

function isOffensiveDecisionChoiceLegal(choice, match) {
  if (!choice || choice.executionOnly || match?.currentDomain === "defense") return false;
  const context = analyzeHighSchoolOffensiveDecisionContext(match);
  const runnerObjectives = new Set(["advanceRunner", "scoreRunner", "avoidDoublePlay"]);
  if (!context.hasRunner && runnerObjectives.has(choice.objective)) return false;
  if (context.twoOuts && ["sacrificeAdvance", "sacrificeFly"].includes(choice.objective)) return false;
  if (context.twoOuts && ["sacrificeAdvance", "sacrificeFly"].includes(choice.route)) return false;
  const checks = {
    runnerOnFirst: context.first,
    runnerOnSecond: context.second,
    runnerOnThird: context.third,
    runnerInScoringPosition: context.scoringPosition,
    anyRunner: context.hasRunner,
    fewerThanTwoOuts: !context.twoOuts,
    doublePlayPossible: context.first && !context.twoOuts
  };
  return (choice.requirements || []).every(requirement => checks[requirement] === true);
}

function getHighSchoolYearOneMatchMomentChoices(match = prepareCurrentHighSchoolYearOneMatch()) {
  const activeSituation = typeof MatchSituationLifecycle !== "undefined"
    ? MatchSituationLifecycle.normalizeSituation(match?.activeSituation) : null;
  if (activeSituation?.type === "plateDecision"
    && activeSituation.lifecycleState === "presented") return getHighSchoolPlateDecisionChoices(match);
  if (match?.simulationPhase === "offensive_agency_ready") return getHighSchoolOffensiveAgencyChoices(match);
  const momentId = getHighSchoolYearOneMomentId(match);
  if (!momentId) return [];
  if (match.momentIndex === 1) {
    return getHighSchoolDefensiveMomentChoices(match);
  }
  ensureHighSchoolBatterAnticipationState(match);
  return buildOffensiveDecisionChoices(match).filter(choice => isOffensiveDecisionChoiceLegal(choice, match));
}

function getHighSchoolPlayingTimeSchoolContext(subject = player) {
  const invitation = typeof getSelectedSchoolInvitation === "function" ? getSelectedSchoolInvitation(subject) : null;
  if (invitation) {
    const selectedCompetition = subject?.schoolInvitationState?.selectedPositionCompetitionContext || invitation.positionCompetitionContext;
    return Object.freeze({
      schoolId: invitation.schoolId || "",
      playingTimeEnvironment: invitation.playingTimeOpportunity || "medium",
      competitionDepth: selectedCompetition?.competitionDensity || invitation.competitionDepth || "medium",
      positionNeed: selectedCompetition?.positionNeed || invitation.positionNeed || invitation.schoolInterest?.positionNeed || "medium",
      projectedRole: invitation.projectedRole || "",
      coachStyle: invitation.coachProfile?.coachStyle || "balanced"
    });
  }
  const route = String(subject?.highSchoolRoute || "");
  if (route.startsWith("強豪")) {
    return Object.freeze({ schoolId: "legacy-powerhouse", playingTimeEnvironment: "low", competitionDepth: "veryHigh", positionNeed: "medium", projectedRole: "", coachStyle: "competition" });
  }
  if (route.startsWith("普通")) {
    return Object.freeze({ schoolId: "legacy-standard", playingTimeEnvironment: "mediumHigh", competitionDepth: "medium", positionNeed: "medium", projectedRole: "", coachStyle: "development" });
  }
  return Object.freeze({ schoolId: "school-context-unavailable", playingTimeEnvironment: "medium", competitionDepth: "medium", positionNeed: "medium", projectedRole: "", coachStyle: "analysis" });
}

function createHighSchoolOpportunityReadinessSnapshot(requestedPosition, subject = player) {
  const school = getHighSchoolPlayingTimeSchoolContext(subject);
  return PlayingTimeGameExposure.createOpportunityReadinessSnapshot({
    subject,
    playerId: [subject.name || "player", subject.characterGenesis?.shape || "", school.schoolId].join("|"),
    position: requestedPosition || subject.primaryPosition || "內野手",
    capabilityProvider: getDefensiveSimulationCapability,
    positionAssessmentProvider: getPositionAssessment
  });
}

function createHighSchoolPlayingTimeOpportunity(options = {}) {
  if (typeof PlayingTimeGameExposure === "undefined") return null;
  const requestedPosition = options.requestedPosition || player.primaryPosition || "內野手";
  const school = getHighSchoolPlayingTimeSchoolContext(player);
  const readinessSnapshot = createHighSchoolOpportunityReadinessSnapshot(requestedPosition, player);
  const opportunityIndex = Math.max(1, Number(options.opportunityIndex) || 1);
  const schoolYearIdentity = player.schoolInvitationState?.selectedSchoolYearRosterIdentity?.identity
    || `${school.schoolId}|legacy-high-school-year-one`;
  const highSchoolYear = Math.max(1, Math.min(3, Math.floor(Number(options.highSchoolYear) || 1)));
  const yearPhase = highSchoolYear === 1 ? "high-school-year-one" : `high-school-year-${highSchoolYear}`;
  const opportunityPhase = options.opportunityPhase || (opportunityIndex === 1 ? "autumn-exhibition" : "post-autumn-evaluation");
  const resolved = PlayingTimeGameExposure.resolveStartingOpportunity({
    matchId: options.matchId,
    readinessSnapshot,
    opportunitySeed: [player.capabilityState?.settlementId || player.capabilityState?.version || "capability", schoolYearIdentity, yearPhase, opportunityPhase, opportunityIndex, options.matchId || "match"].join("|"),
    actualRole: options.actualRole,
    projectedRole: school.projectedRole,
    playingTimeEnvironment: school.playingTimeEnvironment,
    competitionDepth: school.competitionDepth,
    positionNeed: school.positionNeed,
    coachUsageStyle: school.coachStyle,
    evaluationTrend: options.evaluationTrend,
    previousActualExposure: options.previousActualExposure,
    coachTrust: options.includeDynamicReadiness ? player.relationships?.coachTrust : undefined,
    health: options.includeDynamicReadiness ? player.body : undefined,
    stableVariationSeed: options.stableVariationSeed,
    directStartForced: options.directStartForced === true,
    gameContext: { gameType: "highSchoolExhibition", inning: 0, expectedGameImportance: "regular", importance: "regular", leverage: "normal", scoreMargin: 0 }
  });
  if (!options.preserveDecisionId) return resolved;
  return Object.freeze({
    ...cloneSchoolInvitationValue(resolved),
    decisionId: options.preserveDecisionId,
    opportunitySeed: options.preserveOpportunitySeed || resolved.opportunitySeed
  });
}

function isCanonicalHighSchoolYearThreeRoute() {
  return Number(player.highSchoolYearTransitionState?.currentHighSchoolYear) === 3
    && Boolean(player.schoolInvitationState?.selectedSchoolYearRosterIdentity?.identity);
}

function chooseHighSchoolYearThreePreparation(index) {
  if (player.chapter !== "青棒關鍵年" || player.criticalYearStep !== 0 || player.highSchoolCareerPreparation) return false;
  const codes = ["defensive-footwork", "power-hitting", "recovery"];
  const code = codes[index];
  if (!code) return false;
  const result = BaseballTrainingResolver.resolveTraining(createTrainingPlayerSnapshot(), code);
  const applied = applyResolvedTrainingResult(result, "critical_offseason");
  if (!applied.ok) return false;
  player.highSchoolCareerPreparation = { version: "hs-y3-preparation-v1", code, developmentResult: applied.developmentApplication?.result || null };
  player.criticalYearStep = 1;
  ensureHighSchoolYearThreeOpportunity();
  showCurrentEvent();
  const development = player.highSchoolCareerPreparation.developmentResult;
  showNotice(development
    ? `高三準備完成：${skillLabels[development.targetSkill] || "棒球能力"}累積 ${development.progressGained} 點成長進度；出場安排已讀取訓練後的能力與身體狀態。`
    : "恢復準備完成；出場安排已讀取目前身體狀態。", "success");
  return true;
}

function ensureHighSchoolYearThreeOpportunity() {
  if (!isCanonicalHighSchoolYearThreeRoute() || !player.highSchoolCareerPreparation) return null;
  if (player.highSchoolNextOpportunity?.matchId === "hs-y3-final-competition-1") return player.highSchoolNextOpportunity;
  if (player.highSchoolYearThreeMatchHistory?.length) return null;
  const competition = refreshSelectedPositionCompetitionContext(player, player.primaryPosition)
    || player.schoolInvitationState.selectedPositionCompetitionContext;
  const previous = [...(player.highSchoolOpportunityHistory || [])].reverse().find(item => item.actualExposure)?.actualExposure || null;
  const decision = createHighSchoolPlayingTimeOpportunity({
    matchId: "hs-y3-final-competition-1", actualRole: player.highSchoolRoleCode,
    requestedPosition: competition?.position || player.primaryPosition, highSchoolYear: 3,
    opportunityIndex: 1, opportunityPhase: "final-competition", includeDynamicReadiness: true,
    evaluationTrend: player.highSchoolCompetitionEvaluation?.trendScore, previousActualExposure: previous
  });
  const unavailable = player.body.injuryRisk >= 10 || player.body.pain >= 7;
  player.highSchoolNextOpportunity = cloneSchoolInvitationValue({ ...decision,
    ...(unavailable ? { plannedUsage: { ...decision.plannedUsage, appearanceType: "noAppearance" }, healthUnavailable: true } : {}),
    highSchoolYear: 3, opportunityIndex: 1, phase: "final-competition", competitionSnapshot: competition,
    evaluationIdentity: player.highSchoolCompetitionEvaluation?.evaluationIdentity || ""
  });
  player.highSchoolOpportunityHistory = HighSchoolCompetitionReassessment.recordOpportunity(player.highSchoolOpportunityHistory, {
    opportunity: player.highSchoolNextOpportunity, opportunityIndex: 1, roleAtCreation: player.highSchoolRoleCode
  });
  return player.highSchoolNextOpportunity;
}

function prepareHighSchoolYearThreeMatch() {
  if (player.highSchoolMatch?.id === "hs-y3-final-competition-1") return player.highSchoolMatch;
  const opportunity = ensureHighSchoolYearThreeOpportunity();
  if (!opportunity) throw new Error("高三正式比賽缺少完成準備後的出場安排。");
  return prepareHighSchoolYearOneMatch({matchId: opportunity.matchId, eventId: "critical_tournament",
    matchType: "final-competition", opponent: "高三最終交流評估對手", opponentRosterId: "hs-y3-final-regional-opponent",
    highSchoolYear: 3, opportunityIndex: 1, opportunityPhase: "final-competition", opportunityDecision: opportunity});
}

function ensureHighSchoolCareerOffers() {
  if (player.highSchoolCareerSettlement) return player.highSchoolCareerSettlement;
  if (!isCanonicalHighSchoolYearThreeRoute() || player.chapter !== "青棒關鍵年" || player.criticalYearStep !== 7
    || !player.highSchoolYearThreeMatchHistory?.length || !player.highSchoolMatch?.eventSettlementApplied) return null;
  const intent = hasFlag("family_declared_pro") || hasFlag("entered_high_school_draft") ? "draft" : "open";
  const evidence = HighSchoolCareerEvaluation.derive(player, {
    intent, positionFit: getPositionAssessment(player.seasonPosition)?.rating || 0
  });
  const offerSet = HighSchoolCareerOffers.generate(evidence);
  if (!offerSet?.offers.length) return null;
  player.highSchoolCareerSettlement = {
    version: "high-school-career-settlement-v1", settlementIdentity: `${offerSet.offerSetIdentity}|settlement`,
    evidence: cloneSchoolInvitationValue(evidence), offerSet, selectedOffer: null, careerExit: "", appliedSettlementIdentity: ""
  };
  return player.highSchoolCareerSettlement;
}

function selectHighSchoolCareerOffer(offerId) {
  if (getCurrentEventId() !== "critical_exit_choice") return false;
  const result = HighSchoolCareerOffers.commitHighSchoolCareerChoice(player, offerId);
  if (!result.ok) return false;
  player.criticalYearStep = 8;
  evaluateCriticalYear();
  showCurrentEvent();
  return true;
}

function getHighSchoolCareerSummaryText() {
  const state = player.highSchoolCareerSettlement;
  if (!state) return "高中職涯資料尚未完成。";
  const e = state.evidence;
  const labels = HighSchoolCompetitionReassessment.ROLE_LABELS;
  const roles = e.roleJourney.years.map(item => `高${["一","二","三"][item.year-1]}：${labels[item.startingRole] || "未記錄"} → ${labels[item.finalRole] || "未記錄"}`).join("\n");
  const matches = e.formalMatches.years.map(item => `高${["一","二","三"][item.year-1]}正式比賽 ${item.matches.length} 場；${item.matches.reduce((n,m)=>n+m.plateAppearances,0)} 打席、${item.matches.reduce((n,m)=>n+m.defensiveInnings,0)} 局守備`).join("\n");
  const reasons = (state.selectedOffer?.reasonCodes || []).map(code => HighSchoolCareerOffers.REASONS[code] || "仍需進一步評估").join("；");
  const settledOpportunities = e.opportunityHistory.filter(item => item.actualExposure);
  const opportunities = `出場安排紀錄 ${e.opportunityHistory.length} 筆；已結算 ${settledOpportunities.length} 次，其中 ${settledOpportunities.filter(item => !item.actualExposure.participated).length} 次未上場。`;
  return `${roles}\n\n${matches}\n${opportunities}\n正式參賽樣本：${e.performanceProof.sampleCount}；證據可信度：${Math.round(e.performanceProof.confidence*100)}%。\n能力成長：平均 ${e.developmentTrajectory.growth.toFixed(1)}；訓練／比賽成長紀錄 ${e.developmentTrajectory.history.length} 筆。\n累積競爭趨勢：${{positive:"上升",negative:"承壓",neutral:"持平"}[e.competitionProof.recentTrend] || "持平"}。\n疲勞 ${e.healthRisk.fatigue}；疼痛 ${e.healthRisk.pain}；傷病風險 ${e.healthRisk.injuryRisk}。\n${e.positionProfile.pitchingEvidenceUnavailable ? "投手正式投球證據尚未建立；本次不以投球實績提供職業邀請。\n" : ""}\n可選入口 ${state.offerSet.offers.length} 個；你的選擇：${state.selectedOffer?.careerExit || "尚未選擇"}。\n${reasons}`;
}

function getHighSchoolYearThreeEvent(eventId) {
  const original = criticalYearEvents[eventId] || pacingEvents[eventId];
  if (eventId === "transition_draft_day" && player.highSchoolCareerSettlement?.selectedOffer) {
    return {...careerTransitionEvents[eventId], text: "你帶著高中累積的證據進入選秀與測試窗口。先前的觀察興趣不是指名保證；接下來仍要接受組織評估。"};
  }
  if (!original) return null;
  if (eventId === "critical_offseason") return {...original, choices: [
    {text:"練習守備腳步與第一步反應"}, {text:"集中打擊與爆發力"}, {text:"降低疲勞，完成恢復"}
  ]};
  if (eventId === "critical_tournament") return {...original, title:"高三最後一次正式實戰評估",
    text: () => getHighSchoolYearOneMatchPresentation(prepareHighSchoolYearThreeMatch()),
    get choices() { return getHighSchoolYearOneMatchMomentChoices(prepareHighSchoolYearThreeMatch()); }};
  if (eventId === "critical_exit_choice") {
    const state = ensureHighSchoolCareerOffers();
    if (!state) return {...original,text:"正式實戰與職涯資料尚未完成，暫時無法選擇出口。",choices:[]};
    const unavailable = state.offerSet.eligibility.routes.filter(item=>!item.eligible).map(item=>`${{draft:"選秀",college:"大學",amateur:"業餘",rehab:"復健"}[item.route]}：${item.reasonCodes.map(code=>HighSchoolCareerOffers.REASONS[code]).join("、")}`).join("\n");
    return {...original,title:"畢業前可選擇的入口",text:`系統依三年能力、正式出場、健康與課業整理了以下入口。選擇只決定下一段發展方向，並不保證未來主力位置。\n${unavailable}`,
      choices:state.offerSet.offers.map(offer=>({text:`${offer.careerExit}（${offer.confidence==="low"?"觀察／測試":offer.confidence==="moderate"?"有正式關注":"發展入口"}）：${offer.reasonCodes.map(code=>HighSchoolCareerOffers.REASONS[code]).join("、")}`,offerId:offer.offerId}))};
  }
  if (eventId === "critical_year_result") return {...original,text:()=>getHighSchoolCareerSummaryText()};
  if (eventId === "critical_public_attention") return {...original,title:"如何回應外界詢問",text:()=>{
    const match=player.highSchoolYearThreeMatchHistory?.at(-1);
    return match?.actualExposure?.participated ? `比賽紀錄留下了你的 ${match.actualExposure.plateAppearances} 個打席、${match.actualExposure.defensiveInnings} 局守備。你如何回應外界詢問？` : "這次比賽沒有你的正式上場紀錄。你仍可整理能力與發展方向供外界了解，但這不等於比賽實績。";
  },choices:original.choices.map(choice=>({...choice,text:choice.text.replace("下一場任務","下一階段準備")}))};
  if (eventId === "critical_injury") return {...original,title:"正式評估後的身體回報",text:()=>`最後一次正式評估後，你和防護員檢視目前的負荷：疲勞 ${player.body.fatigue}、疼痛 ${player.body.pain}、傷病風險 ${player.body.injuryRisk}。接下來的發展安排需反映這些限制。`,choices:original.choices.map(choice=>{
    const copy={...choice,careerEffects:{...choice.careerEffects}}; delete copy.careerEffects.recentPerformance;
    return {...copy,text:choice.text.replace("退出下一場","調整後續負荷").replace("把最後大賽打完","繼續承擔負荷"),memory:"你與防護員重新確認下一段發展的健康限制；這不會新增任何比賽實績。"};
  })};
  if (eventId === "critical_scout_interview") return {...original,title:"整理下一階段的球員資料",text:"教練協助你整理能力、正式參賽紀錄與健康資料。你可以說明未來方向；訪談印象不會替代比賽證據。"};
  if (eventId === "critical_family") return {...original,text:"家人把升學、選秀與繼續培養的資料放在桌上，詢問你希望承擔哪一種風險。你可以表達意願；真正開放的入口仍須依能力、正式證據、課業與健康決定。"};
  return original;
}

function isCanonicalHighSchoolYearTwoRoute() {
  return player.chapter === "青棒第二年"
    && Number(player.highSchoolYearTransitionState?.currentHighSchoolYear) === 2
    && Boolean(player.schoolInvitationState?.selectedSchoolYearRosterIdentity?.identity);
}

function refreshHighSchoolYearTwoSpringOpportunity() {
  const existing = player.highSchoolNextOpportunity;
  if (!existing || existing.matchId !== "hs-y2-spring-evaluation-1" || Number(existing.highSchoolYear) !== 2) return null;
  const refreshed = createHighSchoolPlayingTimeOpportunity({
    matchId: existing.matchId,
    actualRole: player.highSchoolRoleCode,
    requestedPosition: existing.requestedPosition || existing.assignedPosition || player.primaryPosition,
    highSchoolYear: 2,
    opportunityIndex: 1,
    opportunityPhase: "year-two-spring-evaluation",
    evaluationTrend: player.highSchoolCompetitionEvaluation?.trendScore,
    previousActualExposure: existing.previousActualExposure,
    includeDynamicReadiness: true,
    stableVariationSeed: existing.opportunitySeed || existing.decisionId,
    preserveDecisionId: existing.decisionId,
    preserveOpportunitySeed: existing.opportunitySeed
  });
  player.highSchoolNextOpportunity = cloneSchoolInvitationValue({
    ...refreshed,
    highSchoolYear: 2,
    opportunityIndex: 1,
    phase: "year-two-spring-evaluation",
    evaluationIdentity: existing.evaluationIdentity || player.highSchoolCompetitionEvaluation?.evaluationIdentity || "",
    previousMatchId: existing.previousMatchId || "",
    competitionSnapshot: cloneSchoolInvitationValue(player.schoolInvitationState?.selectedPositionCompetitionContext || existing.competitionSnapshot || {}),
    readinessRefresh: {
      version: "hs-y2-opportunity-readiness-refresh-v1",
      status: "refreshed",
      coachTrust: Number(player.relationships?.coachTrust) || 0,
      fatigue: Number(player.body?.fatigue) || 0,
      pain: Number(player.body?.pain) || 0,
      injuryRisk: Number(player.body?.injuryRisk) || 0
    }
  });
  player.highSchoolOpportunityHistory = HighSchoolCompetitionReassessment.recordOpportunity(player.highSchoolOpportunityHistory, {
    opportunity: player.highSchoolNextOpportunity,
    opportunityIndex: 1,
    roleAtCreation: player.highSchoolRoleCode
  });
  player.highSchoolRoleContext.opportunity = getHighSchoolPlayingTimeAssignmentText(player.highSchoolNextOpportunity);
  return player.highSchoolNextOpportunity;
}

function ensureHighSchoolYearTwoSpringOpportunity() {
  if (player.highSchoolNextOpportunity?.matchId === "hs-y2-spring-evaluation-1") {
    return refreshHighSchoolYearTwoSpringOpportunity();
  }
  if (!isCanonicalHighSchoolYearTwoRoute()) return null;
  const competition = player.schoolInvitationState?.selectedPositionCompetitionContext || {};
  const priorExposure = [...(player.highSchoolOpportunityHistory || [])].reverse().find(item => item.actualExposure)?.actualExposure || null;
  const opportunity = createHighSchoolPlayingTimeOpportunity({
    matchId: "hs-y2-spring-evaluation-1",
    actualRole: player.highSchoolRoleCode,
    requestedPosition: competition.position || player.primaryPosition,
    highSchoolYear: 2,
    opportunityIndex: 1,
    opportunityPhase: "year-two-spring-evaluation",
    evaluationTrend: player.highSchoolCompetitionEvaluation?.trendScore,
    previousActualExposure: priorExposure,
    includeDynamicReadiness: true
  });
  player.highSchoolNextOpportunity = cloneSchoolInvitationValue({
    ...opportunity,
    highSchoolYear: 2,
    opportunityIndex: 1,
    phase: "year-two-spring-evaluation",
    evaluationIdentity: player.highSchoolCompetitionEvaluation?.evaluationIdentity || "",
    previousMatchId: player.highSchoolYearOneMatchHistory?.at(-1)?.matchId || "",
    competitionSnapshot: cloneSchoolInvitationValue(competition),
    recoverySource: "canonical-y2-spring-opportunity-recovery"
  });
  player.highSchoolOpportunityHistory = HighSchoolCompetitionReassessment.recordOpportunity(player.highSchoolOpportunityHistory, {
    opportunity: player.highSchoolNextOpportunity,
    opportunityIndex: 1,
    roleAtCreation: player.highSchoolRoleCode
  });
  return refreshHighSchoolYearTwoSpringOpportunity();
}

function ensureHighSchoolYearTwoAutumnOpportunity() {
  if (player.highSchoolNextOpportunity?.matchId === "hs-y2-autumn-evaluation-2") return player.highSchoolNextOpportunity;
  if (!isCanonicalHighSchoolYearTwoRoute() || player.highSchoolYearTwoStep < 6) return null;
  const competition = player.schoolInvitationState?.selectedPositionCompetitionContext || {};
  const spring = (player.highSchoolYearTwoMatchHistory || []).find(item => item.matchId === "hs-y2-spring-evaluation-1");
  const opportunity = createHighSchoolPlayingTimeOpportunity({
    matchId: "hs-y2-autumn-evaluation-2",
    actualRole: player.highSchoolRoleCode,
    requestedPosition: competition.position || player.primaryPosition,
    highSchoolYear: 2,
    opportunityIndex: 2,
    opportunityPhase: "year-two-autumn-evaluation",
    evaluationTrend: player.highSchoolCompetitionEvaluation?.trendScore,
    previousActualExposure: spring?.actualExposure || null,
    includeDynamicReadiness: true
  });
  player.highSchoolNextOpportunity = cloneSchoolInvitationValue({
    ...opportunity,
    highSchoolYear: 2,
    opportunityIndex: 2,
    phase: "year-two-autumn-evaluation",
    evaluationIdentity: player.highSchoolCompetitionEvaluation?.evaluationIdentity || "",
    previousMatchId: spring?.matchId || "",
    competitionSnapshot: cloneSchoolInvitationValue(competition)
  });
  player.highSchoolOpportunityHistory = HighSchoolCompetitionReassessment.recordOpportunity(player.highSchoolOpportunityHistory, {
    opportunity: player.highSchoolNextOpportunity,
    opportunityIndex: 2,
    roleAtCreation: player.highSchoolRoleCode
  });
  player.highSchoolRoleContext.opportunity = getHighSchoolPlayingTimeAssignmentText(player.highSchoolNextOpportunity);
  return player.highSchoolNextOpportunity;
}

function getHighSchoolPlayingTimeAssignmentText(decision) {
  if (decision?.pitcherExposureDeferred) return "本場投手使用仍由既有比賽流程處理，不套用野手出賽安排";
  if (decision?.plannedUsage?.appearanceType === "start") {
    return decision.exposureSource === "direct-start-forced"
      ? `本次直接開局把你排進${decision.assignedPosition || "守備"}先發，從開賽起進入守備與打序`
      : `教練把你排進本場${decision.assignedPosition || "守備"}先發，實際任務仍由場上局面決定`;
  }
  if (decision?.plannedUsage?.appearanceType === "noAppearance") return "本場先從板凳觀察；是否獲得實際上場機會仍由比賽局勢決定";
  return `本場先從板凳待命，教練預計在${decision.plannedUsage.entryInning || 5}局後依比分與守位需求決定是否換你上場`;
}

function getHighSchoolPlayerTeamSide(match) {
  return match?.matchContext ? (match.matchContext.playerTeamId === match.matchContext.homeTeamId ? "home" : "away") : "home";
}

function getHighSchoolOpponentTeamSide(match) {
  return getHighSchoolPlayerTeamSide(match) === "home" ? "away" : "home";
}

function getHighSchoolPlayerScoreDifference(match) {
  return (Number(match?.scores?.[getHighSchoolPlayerTeamSide(match)]) || 0) - (Number(match?.scores?.[getHighSchoolOpponentTeamSide(match)]) || 0);
}

function prepareHighSchoolYearOneMatch(options = {}) {
  assertHighSchoolMatchCapabilityAdmission(player);
  if (options.matchContext && typeof MatchContextFoundation === "undefined") throw new Error("Explicit match context requires MatchContextFoundation");
  const targetMatchId = options.matchId || "hs-y1-autumn-exhibition";
  const targetEventId = options.eventId || "high_school_showcase";
  const highSchoolYear = Math.max(1, Math.min(3, Math.floor(Number(options.highSchoolYear) || 1)));
  const opportunityIndex = Math.max(1, Number(options.opportunityIndex) || 1);
  if (player.highSchoolMatch?.id === targetMatchId) {
    const match = player.highSchoolMatch;
    if (options.matchContext) {
      if (!match.matchContext) throw new Error("Existing match has no explicit context; cannot reassign a started match");
      const requested = MatchContextFoundation.normalizeMatchContext({...match.matchContext, ...options.matchContext});
      if (JSON.stringify(requested) !== JSON.stringify(match.matchContext)) throw new Error("Existing match context cannot change");
    }
    if (match.completed || (typeof match.simulationPhase === "string" && match.rosters?.home?.lineup?.length === 9 && match.rosters?.away?.lineup?.length === 9)) {
      match.currentMomentId = getHighSchoolYearOneMomentId(match);
      if (!match.completed && match.currentDomain === "defense" && isInfieldDecisionFamilyPosition(match.developmentPositionOverride || match.position) && match.defensiveSituation?.familyId !== "infield") {
        buildInfieldMeaningfulMoment(match, player);
        match.currentAssignment = getHighSchoolDefensiveSituationText(match);
        setHighSchoolCoachTacticalDirection(match);
      }
      return match;
    }
  }
  const code = ["starter", "rotation", "bench"].includes(player.highSchoolRoleCode) ? player.highSchoolRoleCode : "bench";
  if (highSchoolYear === 1 && !player.highSchoolYearOneStartingRole) player.highSchoolYearOneStartingRole = code;
  const roleAssignments = {
    starter: { lineupStatus: "starter", entryWindowInning: 1, history: `以${player.primaryPosition || "守備"}先發，從開賽起進入守備與打序` },
    rotation: { lineupStatus: "bench", entryWindowInning: 4, history: `本場先從板凳待命，預計在中段代打並接替${player.primaryPosition || "守備"}` },
    bench: { lineupStatus: "bench", entryWindowInning: 5, history: `本場先從板凳觀察，等待中後段代打與短局守備機會` }
  };
  const position = player.primaryPosition || "內野手";
  const requestedDevelopmentPosition = opportunityIndex === 1 && infieldPositions.includes(pendingHighSchoolMatchPositionOverride)
    ? pendingHighSchoolMatchPositionOverride : "";
  if (requestedDevelopmentPosition && !isDevelopmentTestPositionLegalForThrowingHand(requestedDevelopmentPosition, player.throws, player.age)) {
    throw new Error(getDevelopmentTestPositionLegalityMessage(requestedDevelopmentPosition, player.throws));
  }
  const developmentPositionOverride = requestedDevelopmentPosition;
  const suppliedOpportunity = options.opportunityDecision || null;
  const simulationSeed = suppliedOpportunity
    ? createHighSchoolMatchSimulationSeedFromIdentity(suppliedOpportunity.decisionId || suppliedOpportunity.matchId)
    : createHighSchoolMatchSimulationSeed();
  const directStartForced = highSchoolYear === 1 && opportunityIndex === 1
    && Array.isArray(player.flags) && player.flags.includes("direct_start_history");
  const opportunityDecision = suppliedOpportunity || createHighSchoolPlayingTimeOpportunity({
    matchId: targetMatchId,
    actualRole: code,
    requestedPosition: developmentPositionOverride || position,
    directStartForced,
    opportunityIndex,
    opportunityPhase: options.opportunityPhase || "autumn-exhibition",
    highSchoolYear
  });
  if ((suppliedOpportunity || opportunityIndex > 1) && (!opportunityDecision || opportunityDecision.matchId !== targetMatchId)) {
    throw new Error(`高中第 ${highSchoolYear} 年第 ${opportunityIndex} 次實戰必須直接消費相同 match identity 的既有 Opportunity。`);
  }
  if (opportunityDecision && typeof HighSchoolCompetitionReassessment !== "undefined") {
    player.highSchoolOpportunityHistory = HighSchoolCompetitionReassessment.recordOpportunity(player.highSchoolOpportunityHistory, {
      opportunity: opportunityDecision,
      opportunityIndex,
      roleAtCreation: code
    });
  }
  const plannedAppearance = opportunityDecision?.plannedUsage?.appearanceType || (code === "starter" ? "start" : "lateGameAppearance");
  const starts = plannedAppearance === "start";
  const roleAssignment = opportunityDecision
    ? {
      lineupStatus: starts ? "starter" : "bench",
      entryWindowInning: starts ? 1 : Math.max(5, Number(opportunityDecision.plannedUsage.entryInning) || 5),
      history: getHighSchoolPlayingTimeAssignmentText(opportunityDecision)
    }
    : roleAssignments[code];
  const assignedPosition = opportunityDecision?.assignedPosition || developmentPositionOverride || position;
  const developmentTestCapabilityOverride = developmentPositionOverride
    ? createDevelopmentMatchPositionTestCapabilityOverride(developmentPositionOverride, player) : null;
  const selectedSchoolRoster = materializeSelectedHighSchoolRoster(player, {
    rosterRole: starts ? "starter" : "bench",
    playerPosition: assignedPosition
  });
  const rosters = createHighSchoolMatchSimulationRoster(
    starts ? "starter" : code === "starter" ? "bench" : code,
    assignedPosition,
    simulationSeed,
    selectedSchoolRoster,
    options.opponentRosterId || "regional-power-school"
  );
  const matchContext = typeof MatchContextFoundation !== "undefined" ? MatchContextFoundation.createMatchContext({
    matchId: targetMatchId,
    playerTeamId: rosters.home.teamRoster?.teamId || "home",
    opponentTeamId: rosters.away.teamRoster?.teamId || "away",
    matchOrigin: options.matchType === "final-competition" ? "officialCompetition" : "developmentMatch",
    legacyFallback: !options.matchContext,
    ...options.matchContext
  }) : null;
  if (matchContext && (matchContext.matchId !== targetMatchId || matchContext.playerTeamId !== (rosters.home.teamRoster?.teamId || "home") || matchContext.opponentTeamId !== (rosters.away.teamRoster?.teamId || "away"))) throw new Error("Match context / roster identity mismatch");
  if (matchContext && MatchContextFoundation.isPlayerAway(matchContext)) [rosters.home, rosters.away] = [rosters.away, rosters.home];
  const playerSide = matchContext ? MatchContextFoundation.playerSide(matchContext) : "home";
  const playerLineupSlot = rosters[playerSide].lineup.findIndex(item => item.id === "player");
  const resolvedCompetitionRules = typeof CompetitionRules !== "undefined"
    ? CompetitionRules.resolveMatchCompetitionRules(matchContext)
    : null;
  const regulationInnings = resolvedCompetitionRules?.rules.regulationInnings
    || Math.max(1, Number(player.highSchoolMatch?.regulationInnings) || 7);
  player.highSchoolMatch = {
    id: targetMatchId,
    matchContext,
    ...(resolvedCompetitionRules ? {
      ruleSetId: resolvedCompetitionRules.ruleSetId,
      rules: resolvedCompetitionRules.rules,
      ruleSetWarning: resolvedCompetitionRules.warning
    } : {}),
    ...(options.scheduleCompetitionRefs || {}),
    eventId: targetEventId,
    matchType: options.matchType || "autumn-exhibition",
    highSchoolYear,
    opportunityIndex,
    opponent: options.opponent || "高橋所屬的地區強校",
    inning: 1,
    half: "上",
    outs: 0,
    scores: { home: 0, away: 0 },
    runners: [null, null, null],
    role: code,
    position,
    assignment: roleAssignment.history,
    matchEntryHistory: `${roleAssignment.history}；${formatHandedness(player.bats, player.throws)}`,
    currentAssignment: starts ? (playerSide === "home" ? "比賽從一局上開始；先完成守備，再等待打序輪到你。" : "比賽從一局上開始；依打序完成進攻，再進入守備。") : "比賽從一局上開始；你在板凳觀察，但場上每個打席都會完整進行。",
    offenseTeam: "away",
    defenseTeam: "home",
    currentBatter: rosters.away.lineup[0]?.id || "",
    battingOrderIndex: { home: 0, away: 0 },
    tiebreakHalfInitialization: null,
    halfInningResolved: false,
    simulationPhase: "full_match_flow",
    simulationCursor: 0,
    simulationSeed,
    simulationLog: [],
    presentedEventCursor: 0,
    scoreboardRevealHalfIndex: 0,
    regulationInnings,
    lineScore: { home: [], away: [] },
    gameRecord: null,
    rosters,
    playerLineupStatus: roleAssignment.lineupStatus,
    playerLineupSlot,
    playerFieldingAssignment: starts ? assignedPosition : "",
    playerEntryWindowInning: roleAssignment.entryWindowInning,
    playerEntryCompleted: starts,
    performanceEvidence: {},
    matchExperience: null,
    gameExposureState: opportunityDecision && typeof PlayingTimeGameExposure !== "undefined"
      ? PlayingTimeGameExposure.createGameExposureState(opportunityDecision) : null,
    developmentFullMatchStart: pendingHighSchoolFullMatchTest,
    playerRunnerLocation: -1,
    momentIndex: 0,
    currentMomentId: highSchoolYearOneMomentIds[0],
    currentDomain: "flow",
    coachTacticalDirection: { domain: "", intent: "", riskPreference: "", priority: "", sourceCoachId: "", presentationStyle: "" },
    coachTacticalContextSignature: "",
    opponentTacticalTruth: { code: "", targetRunnerId: "" },
    ballContext: { type: "", family: "", pace: "", label: "", detail: "", timeWindow: "" },
    positionDecisionFamily: "", currentFieldingPosition: starts && (developmentPositionOverride || opportunityDecision?.positionFallbackApplied) ? assignedPosition : "", developmentPositionOverride,
    developmentTestCapabilityOverride, defensiveSituation: {},
    matchDecisionDensityState: createHighSchoolMatchDecisionDensityState(),
    pitcherRuntimeState: null,
    pitcherSequencingDebugTrace: [],
    pitcherObservableHistory: [],
    pitcherTacticalSequenceHistory: [],
    pitcherTacticalDebugTrace: [],
    batterAnticipationState: null,
    prePitchPlanningState: null,
    offensivePlateAppearanceState: null,
    pendingOffensiveOpportunity: null,
    offensivePlayerAgencyState: null,
    offensiveTacticalActionState: null,
    offensiveBuntPAState: null,
    buntBallInPlayState: null,
    pendingDefensiveResumeState: null,
    lastDefensiveResolution: { resultCode: "", tier: "", decisionQuality: "", executionQuality: "", primaryCause: "", secondaryCause: "", causeExplanation: "" },
    pendingHalfInningTermination: null,
    catcherDecisionState: null,
    catcherReassessmentTrigger: null,
    completedMoments: [],
    playerContribution: { strong: 0, mixed: 0, failure: 0, runsCreated: 0, runsScored: 0, hits: 0, walks: 0, outsCreated: 0, errors: 0 },
    previousMomentDecision: "",
    previousMomentOutcome: "",
    passage: "",
    opponentAdjustment: "",
    coachInstruction: starts ? "先跟著比賽完成每個守備與打席。" : "先讀完整比賽流；被叫到時直接接進當下局面。",
    decision: "",
    outcomeTier: "",
    outcome: "",
    consequence: "",
    coachReaction: "現任教練確認你的第一個場上任務。",
    teamReaction: "休息區把下一段比賽交到你手上。",
    performanceSummary: "",
    teamResult: "",
    settled: false,
    pendingGameSettlement: "",
    eventSettlementApplied: false,
    developmentPresentationCompleted: false,
    completed: false
  };
  ensureHighSchoolPitcherRuntimeState(player.highSchoolMatch);
  if (isHighSchoolMatchOpportunityDebugMode()) ensureHighSchoolMatchOpportunityTrace(player.highSchoolMatch);
  setHighSchoolCoachTacticalDirection(player.highSchoolMatch);
  recordHighSchoolMatchSimulationEvent(player.highSchoolMatch, {
    type: "matchEntry", inning: 1, half: "上",
    outs: 0, runners: player.highSchoolMatch.runners,
    scores: player.highSchoolMatch.scores,
    assignment: player.highSchoolMatch.matchEntryHistory
  });
  pendingHighSchoolMatchPositionOverride = "";
  pendingHighSchoolFullMatchTest = false;
  player.highSchoolRoleContext.assignment = roleAssignment.history;
  return player.highSchoolMatch;
}

// Match opportunities are school-to-school fixtures, separate from PlayingTimeGameExposure decisions.
function getHighSchoolScheduleExecutionContext() {
  const school = player.schoolInvitationState;
  const careerYear = Number(player.highSchoolYearTransitionState?.currentHighSchoolYear) || 1;
  const phases = {high_school_showcase:"autumn-exhibition", high_school_followup_evaluation:"post-autumn-evaluation",
    high_school_year_two_spring_game:"year-two-spring-evaluation", high_school_year_two_autumn_stage:"year-two-autumn-evaluation",
    critical_tournament:"final-competition"};
  const seasonPhase = phases[getCurrentEventId()] || player.highSchoolNextOpportunity?.phase;
  if (!school?.generationSeed || !school.selectedSchoolId || !seasonPhase) throw new Error("Schedule requires admitted career and current match phase");
  return {careerId:school.generationSeed, careerYear, seasonPhase, playerSchoolId:school.selectedSchoolId,
    schoolIds:[school.selectedSchoolId, ...(school.invitations || []).map(item => item.schoolId),
      ...(player.competitionFoundation?.teams || []).filter(item => item.teamType === "school").map(item => item.teamId),
      "regional-power-school", "hs-y2-spring-regional-opponent", "hs-y2-autumn-regional-opponent", "hs-y3-final-regional-opponent"],
    // Reference the existing mandatory career stage, not a second tournament calendar.
    mandatorySlots:careerYear === 3 ? [{careerYear:3,seasonPhase:"final-competition",sequence:1,sourceId:"hs-y3-final-competition-1"}] : []};
}

function getHighSchoolMatchOpportunityGenerationInput(options = {}) {
  const eventId = getCurrentEventId();
  const matchEvents = ["high_school_showcase","high_school_followup_evaluation","high_school_year_two_spring_game","high_school_year_two_autumn_stage","critical_tournament"];
  const context = matchEvents.includes(eventId) ? getHighSchoolScheduleExecutionContext() : {
    careerId:player.schoolInvitationState?.generationSeed,careerYear:Number(player.highSchoolYearTransitionState?.currentHighSchoolYear) || 1,
    seasonPhase:eventId,playerSchoolId:player.schoolInvitationState?.selectedSchoolId,mandatorySlots:[],
    schoolIds:(player.schoolInvitationState?.invitations || []).map(school => school.schoolId)
  };
  context.sequence = options.sequence ?? Math.max(1, Number(player.highSchoolNextOpportunity?.opportunityIndex) || 1);
  context.graduated = !/青棒|高中/.test(String(player.chapter || ""));
  const schoolRecords = (player.schoolInvitationState?.invitations || []).map(school => ({
    schoolId:school.schoolId,teamType:"school",sourceRef:`schoolInvitationState:${school.schoolId}`,
    rosterValid:validateSchoolProfile(school).ok && TeamRosterFoundation.validateRoster(school.baseRoster).ok
      && school.baseRoster.teamId === school.schoolId,
    schoolStandard:school.schoolStandard, strengthRef:school.schoolYearRosterIdentity?.identity,
    coachRef:school.coachProfile?.coachId
  }));
  for (const team of player.competitionFoundation?.teams || []) schoolRecords.push({schoolId:team.teamId,teamType:team.teamType,
    sourceRef:`competitionFoundation.teams:${team.teamId}`,rosterValid:team.teamType === "school" && Boolean(team.organizationId)});
  // These IDs already belong to the schedule execution context's legacy match entry points.
  // Reading their template identities does not instantiate or reroll a roster.
  for (const schoolId of context.schoolIds) if (!schoolRecords.some(item => item.schoolId === schoolId)) schoolRecords.push({
    schoolId,teamType:"school",sourceRef:`getHighSchoolScheduleExecutionContext:${schoolId}`,rosterValid:true});
  const sources = [];
  const next = player.highSchoolNextOpportunity;
  if (next?.matchId === "hs-y1-followup-evaluation-2" && context.careerYear === 1 && context.seasonPhase === "post-autumn-evaluation") {
    sources.push({opportunityType:"developmentMatchOpportunity",opponentSchoolId:"regional-power-school",sequence:2,
      source:{type:"developmentSchedule",sourceId:next.matchId},sourceAuthority:"existing",careerYear:1,seasonPhase:context.seasonPhase,
      matchId:next.matchId,plannedContext:{homeTeamId:context.playerSchoolId,awayTeamId:"regional-power-school",assignmentSource:"developmentSchedule"},
      provenance:{reasonCode:"existing-followup-evaluation",foundationSelection:"existingDevelopmentStage"}});
  }
  for (const slot of context.mandatorySlots) if (slot.careerYear === context.careerYear && slot.seasonPhase === context.seasonPhase) {
    sources.push({opportunityType:"officialCompetitionOpportunity",opponentSchoolId:"hs-y3-final-regional-opponent",sequence:slot.sequence,
      source:{type:"competitionCalendar",sourceId:slot.sourceId},sourceAuthority:"existing",careerYear:slot.careerYear,
      seasonPhase:slot.seasonPhase,matchId:slot.sourceId,provenance:{stageRef:slot.sourceId}});
  }
  const history = ["highSchoolYearOneMatchHistory","highSchoolYearTwoMatchHistory","highSchoolYearThreeMatchHistory"]
    .flatMap(key => (player[key] || []).map(record => ({matchId:record.matchId,careerYear:record.highSchoolYear,
      opponentSchoolId:record.competitionContext?.opponentRosterIdentity?.split("|")[0]})));
  return {context,schoolRecords,sources:[...sources,...(options.sources || [])],history,
    relationshipLedger:player.highSchoolExchangeNetwork,currentCoachId:getSelectedSchoolInvitation(player)?.coachProfile?.coachId,
    activeMatch:player.highSchoolMatch?.id ? {id:player.highSchoolMatch.id,completed:player.highSchoolMatch.completed} : null,
    competition:player.competitionFoundation,schedule:player.highSchoolSchedule,
    includeFoundationFallback:options.includeFoundationFallback !== false};
}

function deriveHighSchoolMatchOpportunityCandidates(options = {}) {
  assertHighSchoolMatchCapabilityAdmission(player);
  return HighSchoolMatchOpportunityGeneration.deriveOpportunityCandidates(getHighSchoolMatchOpportunityGenerationInput(options));
}

function deriveHighSchoolOpportunitySelection(options = {}) {
  assertHighSchoolMatchCapabilityAdmission(player);
  return HighSchoolOpportunitySelection.selectOpportunityCandidates({...getHighSchoolMatchOpportunityGenerationInput(options),
    probabilityPolicy:options.probabilityPolicy??"enabled",maxOptionalPerSelectionWindow:options.maxOptionalPerSelectionWindow});
}

function materializeHighSchoolSelectedOpportunities(selection, options = {}) {
  assertHighSchoolMatchCapabilityAdmission(player);
  const input = {...getHighSchoolMatchOpportunityGenerationInput(options),probabilityPolicy:options.probabilityPolicy??"enabled",maxOptionalPerSelectionWindow:options.maxOptionalPerSelectionWindow};
  return HighSchoolOpportunitySelection.materializeSelectedCandidates(player.highSchoolSchedule,selection,input);
}

function ingestHighSchoolCoachSchoolConnection(fact) {
  assertHighSchoolMatchCapabilityAdmission(player);
  const input = getHighSchoolMatchOpportunityGenerationInput();
  const authority = {schoolIds:input.schoolRecords.filter(item=>item.rosterValid).map(item=>item.schoolId),
    coachIds:(player.schoolInvitationState?.invitations||[]).map(item=>item.coachProfile?.coachId).filter(Boolean)};
  const evidence = HighSchoolExchangeNetwork.deriveCoachSchoolEvidence({...fact,careerId:input.context.careerId,
    careerYear:input.context.careerYear,seasonPhase:input.context.seasonPhase,sequence:fact.sequence??input.context.sequence,
    schoolAId:input.context.playerSchoolId},authority);
  HighSchoolExchangeNetwork.appendEvidence(player.highSchoolExchangeNetwork,[evidence]);
  return evidence;
}

function recordHighSchoolExchangeCompletion(match) {
  if (typeof HighSchoolExchangeNetwork === "undefined") return [];
  const evidence = HighSchoolExchangeNetwork.deriveExchangeEvidenceFromCompletedMatch(match,player.highSchoolSchedule);
  if (evidence.length) HighSchoolExchangeNetwork.appendEvidence(player.highSchoolExchangeNetwork,evidence);
  return evidence;
}

function materializeHighSchoolMatchOpportunityCandidate(candidate, options = {}) {
  assertHighSchoolMatchCapabilityAdmission(player);
  const input = getHighSchoolMatchOpportunityGenerationInput(options);
  getHighSchoolScheduleCompetitionRefs(candidate);
  const opportunity = HighSchoolMatchOpportunityGeneration.materializeOpportunityCandidate(player.highSchoolSchedule,candidate,input);
  getHighSchoolScheduleCompetitionRefs(opportunity);
  return opportunity;
}

function offerHighSchoolMatchOpportunity(input) {
  assertHighSchoolMatchCapabilityAdmission(player);
  const context = getHighSchoolScheduleExecutionContext();
  const opportunity = HighSchoolScheduleOpportunity.createOpportunity({...input, careerId:context.careerId,
    careerYear:input.careerYear ?? context.careerYear, seasonPhase:input.seasonPhase || context.seasonPhase, playerSchoolId:context.playerSchoolId});
  if (opportunity.careerYear !== context.careerYear || opportunity.seasonPhase !== context.seasonPhase
    || !context.schoolIds.includes(opportunity.opponentSchoolId)) throw new Error("Opportunity does not belong to current career phase/schools");
  getHighSchoolScheduleCompetitionRefs(opportunity);
  player.highSchoolSchedule ||= HighSchoolScheduleOpportunity.emptyState();
  return HighSchoolScheduleOpportunity.offerOpportunity(player.highSchoolSchedule,opportunity);
}

function getHighSchoolScheduleCompetitionRefs(opportunity) {
  const refs = opportunity.competitionRefs || {};
  if (!refs.competitionEntryId && !refs.competitionEditionId && !opportunity.plannedContext.competitionEditionId) return {};
  const entry = player.competitionFoundation?.entries.find(item => item.entryId === refs.competitionEntryId);
  if (!entry || entry.competitionEditionId !== refs.competitionEditionId || entry.teamId !== opportunity.playerSchoolId
    || entry.entryStatus !== "entered" || (opportunity.plannedContext.competitionEditionId
      && opportunity.plannedContext.competitionEditionId !== entry.competitionEditionId)) throw new Error("Schedule requires canonical competition entry/edition/team references");
  return {competitionEntryId:entry.entryId,competitionEditionId:entry.competitionEditionId,competitionTeamId:entry.teamId};
}

function launchHighSchoolScheduleEntry(scheduleEntryId, options) {
  assertHighSchoolMatchCapabilityAdmission(player);
  const state = player.highSchoolSchedule;
  const requestedEntry = state?.entries.find(item => item.scheduleEntryId === scheduleEntryId);
  if (!requestedEntry || !["scheduled", "inProgress"].includes(requestedEntry.status)) throw new Error("Schedule entry cannot launch");
  const context = getHighSchoolScheduleExecutionContext();
  const entry = HighSchoolScheduleOpportunity.assertCanLaunch(state,scheduleEntryId,context,player.highSchoolMatch);
