  // Foundation's no-contest diagnostic so lifecycle recovery still has an owner.
  let runnerThrowTiming = selection ? null : DefensiveRunnerThrowSettlementFoundation.projectExistingTiming({
    stage: decisionThrowState, runnerState: null, windowState: "expired", receiverFact: "unavailable" });
  let firstLegSettlement = null;
  if (selection) {
    const timingArgs = { input, opportunity, selection, throwResolution: thrown,
      runnerState: input.runnerPhysicalStates.find(r => r.runnerId === selection.route.targetRunnerId),
      receiverState: input.receiverState, resolveThirdOut: resolveHighSchoolThirdOutIntegrity };
    runnerThrowTiming = DefensiveRunnerThrowSettlementFoundation.resolveTiming(timingArgs);
    firstLegSettlement = DefensiveRunnerThrowSettlementFoundation.deriveSettlement({ ...timingArgs, timing: runnerThrowTiming });
  }
  const firstOut = firstLegSettlement?.outRecorded === true;
  const continuationWindow = handoff.timingWindows.relayToFirstWindow.state;
  const isDoublePlay = choice.infieldRoute === "doublePlay";
  // Relay completion reuses the established 2B/SS receive-turn-deliver model.
  const relay = resolveInfieldRelayToFirst(situation, firstOut, sample, continuationWindow, receiverCapabilities);
  const secondOut = isDoublePlay && firstOut && situation.outs < 2 && relay.secondOutAvailable;
  const retirements = firstOut ? [{ runnerId: selection.route.targetRunnerId, targetBase: selection.route.targetBase,
    outType: firstLegSettlement.playType === "batterRunner" ? "batterRunnerBeforeFirst" : firstLegSettlement.playType === "force" ? "force" : "nonForceTag", sequence: 1 }] : [];
  if (secondOut) retirements.push({ runnerId: situation.batterId, targetBase: "first", outType: "batterRunnerBeforeFirst", sequence: 2 });
  // Complete all committed actors after the first-leg contest. The existing force
  // owner accounts for in-transit runners, collisions, and force removal after outs.
  const runnerSettlement = ForceAdvancement.settleForceAdvancement({ forceChain: situation.forceChain,
    movementIntents: situation.movementIntents, retirements });
  const error = (secureResolution.attemptAvailable && !secureResolution.secured) || thrown?.throwQuality === "offline";
  const resultCode = secondOut ? "twoOuts" : firstOut ? "oneOut" : error ? "error" : "zeroOuts";
  const detailedResult = secondOut ? "completedDoublePlay" : firstOut ? (isDoublePlay ? "secondStageExpired" : "cleanOut")
    : error ? (secureResolution.secured ? "inaccurateThrow" : "fieldingError") : !secureResolution.secured ? "lateFielding"
      : choice.infieldRoute === "controlledNoThrow" ? "controlledNoThrow" : "lateThrow";
  const primaryCause = !secureResolution.secured ? "playerFieldingControl" : thrown?.throwQuality === "offline" ? "playerFirstThrow"
    : !receiverReady && selection?.route.action !== "holdBall"
      ? selection?.route.receiverPosition === "1B" ? "teammateFirstBaseReceive" : selection?.route.receiverPosition === "C" ? "teammateHomeReceive" : "teammatePivot"
      : isDoublePlay && firstOut && !relay.turn && situation.batterSpeed < 8 && continuationWindow !== "narrow" ? "teammatePivot"
        : isDoublePlay && firstOut && relay.turn && !relay.firstBaseReceive ? "teammateFirstBaseReceive"
          : choice.infieldRoute === "controlledNoThrow" ? "balancedExecution"
            : !firstOut || (isDoublePlay && !secondOut) ? "timingWindow" : "balancedExecution";
  const resolution = attachDefensiveOutcomeExplanation(situation, choice, {
    familyId: "infield", route: choice.infieldRoute, routeId: choice.routeId, initialRoute: choice.routeId, activeRoute: choice.routeId,
    playerRole: "initiator", responsibility: situation.responsibility, resultCode, detailedResult,
    tier: secondOut ? "strong" : firstOut || choice.infieldRoute === "controlledNoThrow" ? "mixed" : "failure",
    decisionQuality: choice.advisable === "strong" ? "strong" : choice.advisable === "aggressive" ? "aggressive" : choice.advisable === "conservative" ? "conservative" : "reasonable",
    executionQuality: firstOut ? (isDoublePlay && !secondOut ? "partial" : "complete") : error ? "misplay" : choice.infieldRoute === "controlledNoThrow" ? "controlled" : "late",
    runnerSettlement, runnerSettlementIdentity: situation.runnerSettlementIdentity, outsCreated: runnerSettlement.outsCreated,
    runnerChanges: runnerSettlement.runnerChanges, runnersAfter: runnerSettlement.runnersAfter,
    scoringRunnerIds: runnerSettlement.scoringRunnerIds, runsAllowed: runnerSettlement.runsAllowed, error,
    primaryCause, secondaryCause: "", responsibleActor: primaryCause.startsWith("teammate") ? "teammate" : primaryCause === "timingWindow" ? "timingWindow" : "player",
    playerResponsibility: error ? "major" : "handled", teammateResponsibility: primaryCause.startsWith("teammate") ? "major" : isDoublePlay ? "shared" : "none",
    causeExplanation: primaryCause === "teammatePivot" ? "傳球的接球端未完成接球或轉傳；二壘手與游擊手的責任分開記錄。"
      : primaryCause === "teammateFirstBaseReceive" ? "傳球已進入一壘接球位置，但一壘手未完成接球；傳球與接球責任分開記錄。" : getSecondBaseCauseExplanation(primaryCause, ""),
    playerLeg: { reach: handoff.defensiveAccess.reachResolution.reached ? "completed" : "late",
      control: secureResolution.secured ? "completed" : "failed", transfer: thrown?.releaseQuality === "delayedRelease" ? "delayed" : controlled ? "completed" : "notReached",
      firstThrow: thrown?.throwAttempted ? thrown.throwQuality === "offline" ? "failed" : "completed" : "notAttempted" },
    teammateLeg: { receiver: receiverReady ? "completed" : "notReached", ...(isDoublePlay ? {
      secondBaseReceive: relay.receive ? "completed" : "notCompleted", secondBasePivot: relay.turn ? "completed" : "notCompleted",
      secondBaseSecondThrow: relay.turn ? "completed" : "notCompleted", firstBaseReceive: relay.firstBaseReceive ? "completed" : "notCompleted" } : {}) },
    firstLegState: { status: firstOut ? "completed" : "failed", targetBase: selection?.route.targetBase || null },
    continuationState: { status: secondOut ? "completed" : firstOut && isDoublePlay ? "windowClosed" : "settledByActorOutcomes", targetBase: isDoublePlay ? "first" : null, window: continuationWindow },
    timingResolution: { firstLeg: runnerThrowTiming, firstLegSettlement, relayToFirstWindow: continuationWindow },
    ballContext: situation.ballContext.type, ballDirection: situation.ballDirection, ballDepth: situation.ballDepth,
    batterSpeed: situation.batterSpeed, runnerSpeed: Math.max(...situation.runnerSpeeds.filter(Number.isFinite), 0),
    ...situation.playerCapabilities, firstStage: secureResolution.margin ?? handoff.defensiveAccess.reachResolution.margin,
    secondStage: thrown?.accuracyMargin ?? 0, returnTiming: 0, windows: situation.windows
  });
  return { sample, choice: { routeId: choice.routeId, matchDecision: choice.matchDecision }, secureResolution,
    decisionThrowState,
    runnerThrowTiming, resolution: attachHighSchoolInfieldActionFacts(match, situation, choice, resolution, sample) };
}

function getHighSchoolControlledDecisionInput(match, state = match?.groundBallInPlayState) {
  if (typeof DefensiveDecisionThrowFoundation === "undefined" || state?.settlementApplied || !state?.secureResolution || !state.defensiveAccess?.reachResolution) return null;
  const routeWindows = {};
  for (const id of Object.keys(SECOND_BASE_ROUTE_DEFINITIONS)) {
    routeWindows[id] = getSecondBaseRouteWindow(id, match.defensiveSituation?.routeWindows || {}).state;
  }
  return { physicalTruth: state.physicalTruth, opportunity: getHighSchoolDefensiveOpportunity(match, state.physicalTruth),
    activeRoster: match.rosters[match.defenseTeam], capabilities: state.defensiveAccess.secureCapabilities,
    reachResult: state.defensiveAccess.reachResolution, secureResult: state.secureResolution,
    runners: match.runners, outs: match.outs, inning: match.inning, half: match.half, scores: match.scores,
    batterRunnerId: state.runnerRealization?.batterRunner?.runnerId, forceChain: state.forceChain,
    runnerStates: (state.runnerPhysicalStates || []).filter(r => match.runners.includes(r.runnerId)),
    runnerPhysicalStates: state.runnerPhysicalStates || [], routeWindows };
}

function getHighSchoolControlledDefensiveRoutes(match) {
  const input = getHighSchoolControlledDecisionInput(match);
  return input ? DefensiveDecisionThrowFoundation.buildDecisionOpportunity(input) : null;
}

function validateHighSchoolGroundLifecycleRoutes(match) {
  const lifecycle = match?.activeSituation;
  if (lifecycle?.type !== "groundBallDefensiveDecision") return;
  // A historical save may omit one copy; every copy that is present must
  // describe the same legal intent. Do not prefer decision over execution.
  const routes = [lifecycle.decision, lifecycle.executionState]
    .filter(copy => copy && Object.prototype.hasOwnProperty.call(copy, "selectedRoute"))
    .map(copy => copy.selectedRoute);
  if (routes.some(route => typeof route !== "string" || !route)
    || routes.some(route => route !== routes[0])
    || (Array.isArray(lifecycle.legalRoutes) && lifecycle.legalRoutes.length > 0
      && routes.some(route => !lifecycle.legalRoutes.some(choice => (choice.routeId || choice.id || choice.matchDecision) === route)))) {
    throw new Error("Stale ground-ball lifecycle route copies");
  }
  const state = match?.groundBallInPlayState;
  const executionRoute = state?.firstBaseExecution?.choice.routeId
    || state?.thirdBaseExecution?.choice.routeId || state?.shortstopExecution?.choice.routeId
    || state?.decisionThrowState?.preControlIntent;
  if (lifecycle.sourcePhysicalStateRef === state?.identity && executionRoute
    && routes.some(route => route !== executionRoute)) throw new Error("Stale ground-ball lifecycle cached route");
}

function validateHighSchoolDecisionThrowState(match) {
  validateHighSchoolGroundLifecycleRoutes(match);
  const state = match?.groundBallInPlayState;
  if (state?.supported && !state.firstBaseContext && (state.firstBaseExecution
    || match.activeSituation?.contextSnapshot?.firstBaseContext
    || match.activeSituation?.resolution?.executionEvidence?.firstBaseEvidence)) throw new Error("Invalid missing first-base participant context");
  if (state?.firstBaseContext) {
    if (!state.settlementApplied) assertHighSchoolGroundParticipant(match);
    if (state.firstBaseExecution) { validateHighSchoolFirstBaseExecution(match); return; }
    if (state.secureResolution || state.decisionThrowState || state.runnerThrowTiming
      || match.activeSituation?.resolution?.executionEvidence?.firstBaseEvidence) throw new Error("Invalid incomplete first-base execution stages");
  }
  if (state?.supported && state.defensiveAccess?.playerPosition === "三壘手" && !state.thirdBaseExecution
    && (state.secureResolution || state.decisionThrowState || state.runnerThrowTiming
      || match.activeSituation?.resolution?.executionEvidence?.thirdBaseEvidence)) throw new Error("Invalid incomplete 3B execution stages");
  if (state?.thirdBaseExecution) {
    validateHighSchoolThirdBaseExecution(match);
    return;
  }
  if (!state?.decisionThrowState || state.settlementApplied || typeof DefensiveDecisionThrowFoundation === "undefined") return;
  if (state.shortstopExecution) {
    const stored = state.shortstopExecution;
    const choice = getInfieldDecisionChoice(match.defensiveSituation, match, stored.choice.matchDecision);
    if (!choice || choice.routeId !== stored.choice.routeId) throw new Error("Stale SS legal route");
    const fresh = buildHighSchoolShortstopExecution(match, match.defensiveSituation, choice, stored.sample);
    if (!stored.resolution.actionFacts) {
      // New facts are optional for historical executed saves. Validate every
      // pre-existing SS fact against reconstruction without rewriting the source.
      const { actionFacts, executionSample, ...historicalResolution } = fresh.resolution;
      fresh.resolution = historicalResolution;
    }
    if (JSON.stringify(fresh) !== JSON.stringify(stored)
      || JSON.stringify(state.secureResolution) !== JSON.stringify(fresh.secureResolution)
      || JSON.stringify(state.decisionThrowState) !== JSON.stringify(fresh.decisionThrowState)
      || JSON.stringify(state.runnerThrowTiming) !== JSON.stringify(fresh.runnerThrowTiming)) throw new Error("Stale SS execution / timing facts");
    return;
  }
  DefensiveDecisionThrowFoundation.validateStoredStage(state.decisionThrowState, getHighSchoolControlledDecisionInput(match, state));
  const evidence = match.activeSituation?.resolution?.executionEvidence;
  // Historical stages without the new contract retain their existing admission.
  if (evidence?.actionFacts) {
    if (!Number.isFinite(evidence.executionSample) || evidence.executionSample < 0 || evidence.executionSample >= 1) throw new Error("Invalid 2B execution sample");
    const routeId = match.activeSituation.decision?.selectedRoute || state.decisionThrowState.preControlIntent;
    const choice = generateInfieldLegalChoices(match.defensiveSituation, match).find(c => c.routeId === routeId);
    if (!choice) throw new Error("Stale 2B execution route");
    const raw = choice.routeId === "coverSecondFor643" ? resolveSecondBaseCoverage643(match.defensiveSituation, choice, evidence.executionSample)
      : resolveSecondBaseInitiatedRoute(match.defensiveSituation, choice, evidence.executionSample, match);
    const fresh = attachHighSchoolInfieldActionFacts(match, match.defensiveSituation, choice, raw, evidence.executionSample);
    if (JSON.stringify(fresh.actionFacts) !== JSON.stringify(evidence.actionFacts)
      || JSON.stringify(fresh.receiverResolution) !== JSON.stringify(evidence.receiverResolution)
      || fresh.outsCreated !== evidence.outsCreated || fresh.resultCode !== evidence.resultCode) throw new Error("Stale 2B receiver / action facts");
  }
  if (state.runnerThrowTiming && typeof DefensiveRunnerThrowSettlementFoundation !== "undefined") {
    DefensiveRunnerThrowSettlementFoundation.validateProjectedTiming(state.runnerThrowTiming, state.decisionThrowState, state.runnerPhysicalStates,
      match.activeSituation?.resolution?.executionEvidence);
  }
}

function projectHighSchoolControlledDecisionThrow(match, resolution, state = match?.groundBallInPlayState) {
  const input = getHighSchoolControlledDecisionInput(match, state);
  if (!input) return null;
  const opportunity = DefensiveDecisionThrowFoundation.buildDecisionOpportunity(input);
  const intentRoute = resolution.initialRoute || resolution.routeId;
  if (opportunity.status !== "controlledDecision") return { opportunity, preControlIntent: intentRoute, selection: null, throwResolution: null };
  const selection = DefensiveDecisionThrowFoundation.selectDefensiveRoute(opportunity, intentRoute, input);
  const finalRoute = resolution.activeRoute || resolution.routeId;
  const activeSelection = finalRoute === intentRoute ? selection : DefensiveDecisionThrowFoundation.selectDefensiveRoute(opportunity, finalRoute, input);
  const throwResolution = DefensiveDecisionThrowFoundation.projectExistingThrow({ input, opportunity, selection: activeSelection,
    playerLeg: resolution.playerLeg, evidence: { ...resolution.controlEvidence, arm: resolution.arm, throwing: resolution.throwing,
      firstThrowWindow: resolution.windows?.throw } });
  return { opportunity, preControlIntent: intentRoute, selection, activeSelection, throwResolution };
}

function recordGroundBallSituationResolution(match, resolution) {
  if (!match || !resolution || typeof MatchSituationLifecycle === "undefined") return null;
  let situation = MatchSituationLifecycle.normalizeSituation(match.activeSituation);
  if (!situation || situation.type !== MatchSituationLifecycle.TYPES.groundBallDefensiveDecision
    || situation.lifecycleState !== "executing") return situation;
  validateHighSchoolDecisionThrowState(match);
  const handoff = match.groundBallInPlayState;
  if (handoff?.firstBaseExecution && Object.entries(handoff.firstBaseExecution.resolution)
    .some(([key, value]) => JSON.stringify(resolution[key]) !== JSON.stringify(value))) throw new Error("Stale first-base settlement execution facts");
  if (handoff?.thirdBaseExecution && Object.entries(handoff.thirdBaseExecution.resolution)
    .some(([key, value]) => JSON.stringify(resolution[key]) !== JSON.stringify(value))) throw new Error("Stale 3B settlement execution facts");
  if (handoff?.shortstopExecution && Object.entries(handoff.shortstopExecution.resolution)
    .some(([key, value]) => JSON.stringify(resolution[key]) !== JSON.stringify(value))) throw new Error("Stale SS settlement execution facts");
  if (handoff?.supported && !handoff.settlementApplied && !handoff.secureResolution
    && handoff.defensiveAccess?.reachResolution && resolution.playerLeg?.control
    && typeof DefensiveReachSecureFoundation !== "undefined") {
    assertHighSchoolDetailedResponsibility(match, handoff.physicalTruth, "2B", "player");
    const securedHandoff = BattedBallGroundDefense.normalizeHandoff({ ...handoff,
      secureResolution: DefensiveReachSecureFoundation.projectGroundControl(handoff.defensiveAccess.reachResolution, resolution.playerLeg.control, resolution.controlEvidence) });
    const decisionThrowState = projectHighSchoolControlledDecisionThrow(match, resolution, securedHandoff);
    match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({ ...securedHandoff, ...(decisionThrowState ? { decisionThrowState } : {}) });
    if (decisionThrowState && typeof DefensiveRunnerThrowSettlementFoundation !== "undefined") {
      const route = decisionThrowState.activeSelection?.route || decisionThrowState.selection?.route;
      const receiverFact = route?.routeId === "initiate463" ? resolution.teammateLeg?.shortstopReceive
        : route?.routeId === "preventRunHome" && !resolution.reassessed ? resolution.teammateLeg?.catcherReceive : resolution.teammateLeg?.receiver;
      const runnerThrowTiming = DefensiveRunnerThrowSettlementFoundation.projectExistingTiming({ stage: decisionThrowState,
        runnerState: handoff.runnerPhysicalStates?.find(r => r.runnerId === route?.targetRunnerId),
        windowState: resolution.firstLegTimingWindow?.state || "expired", receiverFact: receiverFact || "unavailable",
        tagFact: resolution.homeTagLeg?.arrivalComparison || null });
      match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({ ...match.groundBallInPlayState, runnerThrowTiming });
    }
  }
  if (resolution.reassessment) {
    const remaining = (resolution.reassessment.availableRouteIds || []).map(routeId => ({ routeId }));
    situation = MatchSituationLifecycle.beginReassessment(situation, {
      trigger: resolution.reassessment.reason,
      updatedPhysicalState: {
        firstLegState: resolution.firstLegState || null,
        continuationState: resolution.continuationState || null,
        forceState: resolution.reassessment.forceState || null
      },
      remainingLegalRoutes: remaining,
      requiresDecision: false,
      firstLegApplied: resolution.firstLegState?.status === "completed"
    });
  }
  situation = MatchSituationLifecycle.resolveSituation(situation, {
    physicalOutcomeRef: `${situation.situationId}|physical-resolution`,
    outsDelta: resolution.outsCreated,
    runsDelta: resolution.runsAllowed,
    runnerActorOutcomes: resolution.runnerChanges,
    executionEvidence: match.groundBallInPlayState?.runnerThrowTiming || match.groundBallInPlayState?.shortstopExecution ? resolution : null,
    reason: resolution.reassessment ? "postExecutionReassessmentComplete" : "groundBallExecutionComplete"
  });
  match.activeSituation = situation;
  return situation;
}

function settleAndCloseGroundBallSituation(match) {
  if (!match || typeof MatchSituationLifecycle === "undefined") return null;
  let situation = MatchSituationLifecycle.normalizeSituation(match.activeSituation);
  if (!situation || situation.type !== MatchSituationLifecycle.TYPES.groundBallDefensiveDecision) return situation;
  if (situation.lifecycleState === "resolved") {
    situation = MatchSituationLifecycle.markSettled(situation, {
      identity: `${situation.situationId}|${match.groundBallInPlayState?.identity || "ground-ball"}|settlement`
    });
  }
  if (situation.lifecycleState === "settled") situation = MatchSituationLifecycle.closeSituation(situation);
  if (situation.lifecycleState === "closed") {
    match.lastClosedSituationSummary = MatchSituationLifecycle.createClosedSituationSummary(situation);
    match.activeSituation = null;
  } else {
    match.activeSituation = situation;
  }
  return situation;
}

function abandonActiveMatchSituation(match, reason) {
  if (!match || typeof MatchSituationLifecycle === "undefined") return null;
  const active = MatchSituationLifecycle.normalizeSituation(match.activeSituation);
  if (!active) return null;
  const abandoned = MatchSituationLifecycle.abandonSituation(active, { reason });
  if (abandoned.lifecycleState === "closed") {
    match.lastClosedSituationSummary = MatchSituationLifecycle.createClosedSituationSummary(abandoned);
    match.activeSituation = null;
  } else match.activeSituation = abandoned;
  return abandoned;
}

function restoreHighSchoolMatchAfterDefensiveDecision(match, fallbackPhase = "moment_2_resolved") {
  const activeSituation = typeof MatchSituationLifecycle !== "undefined"
    ? MatchSituationLifecycle.normalizeSituation(match?.activeSituation) : null;
  if (activeSituation && !MatchSituationLifecycle.canResumeSimulation(activeSituation)) return match.simulationPhase;
  const resume = match?.pendingDefensiveResumeState;
  if (resume) {
    match.simulationPhase = resume.simulationPhase || fallbackPhase;
    match.momentIndex = Math.max(0, Math.min(2, Number(resume.momentIndex) || 0));
    match.currentMomentId = resume.currentMomentId || match.currentMomentId;
    match.currentDomain = resume.currentDomain || "flow";
  } else {
    match.simulationPhase = fallbackPhase;
  }
  match.pendingDefensiveResumeState = null;
  return match.simulationPhase;
}

function applyHighSchoolDefensiveSettlementFacts(match, settlement, source = "defensive-play-settlement") {
  if (settlement.settlementApplied) return settlement;
  if (settlement.thirdOut?.settlementReady === false) throw new Error("TIMING_PLAY_UNRESOLVED: settlement cannot commit");
  DefensiveRunnerThrowSettlementFoundation.validateBefore(settlement, match);
  const third = settlement.thirdOut;
  if (settlement.outsAfter !== third.outsAfter || JSON.stringify(settlement.baseChanges) !== JSON.stringify(third.basesAfter)
    || JSON.stringify(settlement.runChanges) !== JSON.stringify(third.legalScoringRunnerIds)) throw new Error("Settlement / third-out mismatch");
  match.outs = third.outsAfter;
  for (const runnerId of settlement.runChanges) scoreHighSchoolMatchRunner(match, runnerId, match.offenseTeam, source, {
    presentationImportance: "hidden", outsOverride: third.halfInningEnded && third.thirdOutType === HIGH_SCHOOL_THIRD_OUT_TYPES.nonForceTag ? settlement.outsBefore : match.outs
  });
  match.runners = settlement.baseChanges.slice();
  if (third.halfInningEnded) match.pendingHalfInningTermination = JSON.parse(JSON.stringify(third));
  syncHighSchoolMatchPlayerRunnerLocation(match);
  return Object.freeze({ ...settlement, settlementApplied: true });
}

function validateHighSchoolStoredDefensiveResolution(match, resolution) {
  const stored = match.activeSituation?.resolution?.executionEvidence;
  if ((match.groundBallInPlayState?.runnerThrowTiming || match.groundBallInPlayState?.shortstopExecution) && stored && JSON.stringify(stored) !== JSON.stringify(resolution)) {
    throw new Error("Stale defensive settlement execution facts");
  }
}

function applyInfieldResolutionToHighSchoolMatch(match, decision, resolution) {
  const situation = match.defensiveSituation;
  const groundBallContext = situation?.groundBallDefensiveContext;
  if (resolution.runnerSettlementIdentity && match.lastDefensiveResolution?.runnerSettlementIdentity === resolution.runnerSettlementIdentity) return match.completedMoments.at(-1) || null;
  if (resolution.runnerSettlementIdentity && resolution.runnerSettlementIdentity !== situation?.runnerSettlementIdentity) throw new Error("Stale infield play identity");
  if (groundBallContext && match.groundBallInPlayState?.settlementApplied) return match.completedMoments.at(-1) || null;
  validateHighSchoolDecisionThrowState(match);
  beginGroundBallSituationDecision(match, decision);
  recordGroundBallSituationResolution(match, resolution);
  validateHighSchoolStoredDefensiveResolution(match, resolution);
  const situationBefore = { inning: match.inning, half: match.half, outs: match.outs, scores: { ...match.scores }, runners: match.runners.slice() };
  const presentation = infieldDecisionFamily.present(situation, resolution, decision);
  const explanation = resolution.defensiveOutcomeExplanation || createDefensiveOutcomeExplanation(situation, getInfieldDecisionChoice(situation, match, decision), resolution);
  const thirdOutResolution = finalizeHighSchoolDefensiveThirdOut(match, situationBefore, resolution);
  const runnerChanges = normalizeHighSchoolTerminalRunnerChanges(resolution, thirdOutResolution);
  if (match.groundBallInPlayState?.runnerThrowTiming && typeof DefensiveRunnerThrowSettlementFoundation !== "undefined") {
    const handoff = match.groundBallInPlayState;
    const settlement = DefensiveRunnerThrowSettlementFoundation.projectExistingSettlement({ timing: handoff.runnerThrowTiming,
      stage: handoff.decisionThrowState, before: situationBefore, resolution, thirdOut: thirdOutResolution });
    const applied = applyHighSchoolDefensiveSettlementFacts(match, settlement, "infield-decision-family");
    match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({ ...handoff, playSettlement: applied });
  } else {
    const settlement = DefensiveRunnerThrowSettlementFoundation.projectInfieldSettlement({
      identity: situation.runnerSettlementIdentity, before: situationBefore, resolution, thirdOut: thirdOutResolution });
    applyHighSchoolDefensiveSettlementFacts(match, settlement, "infield-decision-family");
  }
  resolution = projectHighSchoolInfieldScoredResolution(match, situation, resolution);
  if (resolution.error) match.playerContribution.errors += 1;
  match.playerContribution.outsCreated += resolution.outsCreated;
  syncHighSchoolMatchPlayerRunnerLocation(match);
  const situationAfter = { inning: match.inning, half: match.half, outs: match.outs, scores: { ...match.scores }, runners: match.runners.slice() };
  const consequence = resolution.route === "doublePlay" && resolution.outsCreated === 1
    ? `${resolution.causeExplanation} 合理的雙殺判斷只完成一半。` : resolution.causeExplanation;
  const provisionalResolution = {
    ...resolution,
    runnerChanges,
    runnersAfter: thirdOutResolution.basesAfter,
    scoringRunnerIds: thirdOutResolution.legalScoringRunnerIds,
    runsAllowed: thirdOutResolution.legalScoringRunnerIds.length,
    thirdOutResolution
  };
  // Player error attribution stays separate from the team's official PA result.
  const thirdBaseTeamError = resolution.scorerFacts ? resolution.scorerFacts.batterReachedOnError
    : (resolution.thirdBaseEvidence || resolution.firstBaseEvidence) && resolution.actionFacts.actions
      .some(action => action.errorCharged === true && action.status === "failed");
  const groundBallPhysicalOutcome = groundBallContext && typeof BattedBallGroundDefense !== "undefined"
    ? BattedBallGroundDefense.settleGroundBallPhysicalOutcome(groundBallContext, provisionalResolution) : null;
  const paCompatibilityResult = groundBallPhysicalOutcome && typeof BattedBallGroundDefense !== "undefined"
    ? BattedBallOutcomeMapping.resolveOfficialBallInPlayOutcome({
      physicalTruth: groundBallContext.physicalTruth,
      defenseOutcome: { ...BattedBallGroundDefense.derivePACompatibilityResult(groundBallPhysicalOutcome), settled: true }
    }) : null;
  const batterResult = resolution.batterScoring?.classification === "fieldersChoice" ? "out"
    : (resolution.scorerFacts ? thirdBaseTeamError : resolution.error || thirdBaseTeamError) ? "error"
    : paCompatibilityResult?.result || (resolution.outsCreated > 0 ? "out" : "single");
  const appliedResolution = {
    ...provisionalResolution,
    groundBallPhysicalOutcome,
    paCompatibilityResult,
    ...getHighSchoolInfieldFinalFacts(match, situation, resolution)
  };
  const paEvent = recordHighSchoolMeaningfulPlateAppearance(match, situation.batterId, batterResult, situationBefore, situationAfter, thirdOutResolution.legalScoringRunnerIds.length, appliedResolution);
  if (paCompatibilityResult) Object.assign(paEvent, { physicalOutcomeFlow: "physicalTruthToOfficialOutcome", officialBallInPlayOutcome: JSON.parse(JSON.stringify(paCompatibilityResult)) });
