function applyRoutineDefensiveResolutionToHighSchoolMatch(match, resolution) {
  if (!match || !resolution || resolution.eventClassification !== "playerRoutinePlay") return null;
  if (resolution.runnerSettlementIdentity && match.lastDefensiveResolution?.runnerSettlementIdentity === resolution.runnerSettlementIdentity) return null;
  if (resolution.runnerSettlementIdentity && resolution.runnerSettlementIdentity !== match.defensiveSituation?.runnerSettlementIdentity) throw new Error("Stale infield play identity");
  if (match.groundBallInPlayState?.playSettlement?.settlementApplied) return null;
  validateHighSchoolDecisionThrowState(match);
  beginAutomaticGroundBallSituationExecution(match);
  recordGroundBallSituationResolution(match, resolution);
  validateHighSchoolStoredDefensiveResolution(match, resolution);
  const situation = match.defensiveSituation;
  const situationBefore = {
    inning: match.inning,
    half: match.half,
    outs: match.outs,
    scores: { ...match.scores },
    runners: match.runners.slice()
  };
  const thirdOutResolution = finalizeHighSchoolDefensiveThirdOut(match, situationBefore, resolution);
  const runnerChanges = normalizeHighSchoolTerminalRunnerChanges(resolution, thirdOutResolution);
  if (match.groundBallInPlayState?.runnerThrowTiming && typeof DefensiveRunnerThrowSettlementFoundation !== "undefined") {
    const handoff = match.groundBallInPlayState;
    const settlement = DefensiveRunnerThrowSettlementFoundation.projectExistingSettlement({ timing: handoff.runnerThrowTiming,
      stage: handoff.decisionThrowState, before: situationBefore, resolution, thirdOut: thirdOutResolution });
    const applied = applyHighSchoolDefensiveSettlementFacts(match, settlement, "player-routine-play");
    match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({ ...handoff, playSettlement: applied, settlementApplied: true });
  } else {
    const settlement = DefensiveRunnerThrowSettlementFoundation.projectInfieldSettlement({
      identity: situation.runnerSettlementIdentity, before: situationBefore, resolution, thirdOut: thirdOutResolution });
    applyHighSchoolDefensiveSettlementFacts(match, settlement, "player-routine-play");
  }
  resolution = projectHighSchoolInfieldScoredResolution(match, situation, resolution);
  if (resolution.error) match.playerContribution.errors += 1;
  match.playerContribution.outsCreated += resolution.outsCreated;
  syncHighSchoolMatchPlayerRunnerLocation(match);
  const situationAfter = {
    inning: match.inning,
    half: match.half,
    outs: match.outs,
    scores: { ...match.scores },
    runners: match.runners.slice()
  };
  const thirdBaseTeamError = resolution.scorerFacts ? resolution.scorerFacts.batterReachedOnError
    : (resolution.thirdBaseEvidence || resolution.firstBaseEvidence) && resolution.actionFacts.actions
      .some(action => action.errorCharged === true && action.status === "failed");
  const batterResult = resolution.batterScoring?.classification === "fieldersChoice" ? "out"
    : (resolution.scorerFacts ? thirdBaseTeamError : resolution.error || thirdBaseTeamError) ? "error" : (match.groundBallInPlayState?.shortstopExecution || match.groundBallInPlayState?.thirdBaseExecution || match.groundBallInPlayState?.firstBaseExecution)
    ? resolution.runnerSettlement.outRunnerIds.includes(situation.batterId) ? "out" : "single"
    : resolution.outsCreated > 0 ? "out" : "single";
  const appliedResolution = { ...resolution, runnerChanges, runnersAfter: thirdOutResolution.basesAfter,
    scoringRunnerIds: thirdOutResolution.legalScoringRunnerIds,
    runsAllowed: thirdOutResolution.legalScoringRunnerIds.length, thirdOutResolution,
    ...getHighSchoolInfieldFinalFacts(match, situation, resolution) };
  recordHighSchoolRoutinePlateAppearance(
    match,
    situation.batterId,
    batterResult,
    situationBefore,
    situationAfter,
    thirdOutResolution.legalScoringRunnerIds.length,
    appliedResolution
  );
  getHighSchoolMatchPerformanceEvidence(match, "player").defensiveInvolvements += 1;
  match.lastDefensiveResolution = JSON.parse(JSON.stringify(appliedResolution));
  advanceHighSchoolMatchBattingOrder(match, getHighSchoolOpponentTeamSide(match));
  match.currentDomain = "flow";
  match.currentAssignment = resolution.error
    ? formatHighSchoolMatchWorldState(match, "這次例行守備形成失誤。")
    : resolution.outsCreated > 0
      ? formatHighSchoolMatchWorldState(match, "你完成例行守備出局；下一棒走進打擊區。")
      : formatHighSchoolMatchWorldState(match, "你完成例行處理。" );
  const event = recordHighSchoolMatchSimulationEvent(match, {
    type: "playerRoutinePlay",
    ...getHighSchoolInfieldFinalFacts(match, situation, resolution),
    eventClassification: "playerRoutinePlay",
    decisionTension: resolution.decisionTension,
    presentationImportance: "attention",
    inning: match.inning,
    half: match.half,
    offenseTeam: getHighSchoolOpponentTeamSide(match),
    batterId: situation.batterId,
    currentBatterAfter: match.currentBatter,
    playerPosition: situation.playerPosition,
    ballContext: resolution.ballContext,
    ballDirection: resolution.ballDirection,
    ballDepth: resolution.ballDepth,
    executionRoute: resolution.executionRoute,
    initialRoute: resolution.initialRoute || resolution.routeId || "",
    activeRoute: resolution.activeRoute || resolution.routeId || "",
    fallbackRoute: resolution.fallbackRoute || "",
    playerRole: resolution.playerRole || situation.responsibility?.playerRole || "",
    coverageQuality: resolution.coverageQuality || "",
    upstreamThrowQuality: resolution.upstreamThrowQuality || "",
    decisionQuality: resolution.decisionQuality || "routine",
    executionQuality: resolution.executionQuality || "notApplicable",
    primaryCause: resolution.primaryCause || "",
    secondaryCause: resolution.secondaryCause || "",
    responsibleActor: resolution.responsibleActor || "",
    playerResponsibility: resolution.playerResponsibility || "",
    teammateResponsibility: resolution.teammateResponsibility || "",
    playerLeg: resolution.playerLeg || {},
    teammateLeg: resolution.teammateLeg || {},
    timingResolution: resolution.timingResolution || {},
    resultCode: resolution.resultCode,
    outsCreated: resolution.outsCreated,
    runsAllowed: appliedResolution.runsAllowed,
    error: resolution.error,
    runnerChanges,
    scoringRunnerIds: thirdOutResolution.legalScoringRunnerIds,
    thirdOutResolution,
    before: situationBefore,
    after: situationAfter,
    outs: match.outs,
    scores: match.scores,
    runners: match.runners,
    assignment: match.currentAssignment
  });
  assertHighSchoolMatchStateIntegrity(match, "player-routine-defense");
  settleAndCloseGroundBallSituation(match);
  return event;
}

function applyCatcherResolutionToHighSchoolMatch(match, decision, resolution) {
  if (!match || resolution?.familyId !== "catcher") return null;
  if (resolution.outEventIdentity && match.lastDefensiveResolution?.outEventIdentity === resolution.outEventIdentity) return match.completedMoments.at(-1) || null;
