  const previousText = previous?.participated
    ? `上一場留下 ${previous.plateAppearances || 0} 個打席、${previous.defensiveInnings || 0} 局守備的正式證據。`
    : "上一場沒有實際上場樣本，教練沒有把等待當成負面表現。";
  const roleText = role === "starter"
